            box-shadow: 0 3px 8px rgba(var(--primary-rgb), 0.22);
        }
        .dark-mode .course-tag-chip {
            background: linear-gradient(135deg, rgba(var(--primary-rgb), 0.18), rgba(244, 114, 182, 0.18));
            color: var(--primary);
            border-color: rgba(var(--primary-rgb), 0.3);
        }
        .course-tag-filter-bar {
            display: none;
