        .course-note-preview {
            display: none;
            font-size: 0.8rem;
            line-height: 1.6;
            color: var(--text-dark);
            background: linear-gradient(135deg, rgba(245, 158, 11, 0.08), rgba(245, 158, 11, 0.03));
