            to { opacity: 1; transform: translateY(0); }
        }
        .course-note-preview.open { display: block; }
        .dark-mode .course-note-preview {
            background: linear-gradient(135deg, rgba(251, 191, 36, 0.1), rgba(251, 191, 36, 0.03));
