        }

        /* --- COURSE DEADLINE REMINDER BANNER --- */
        #courseReminderBanner {
            border-radius: 14px;
            margin-bottom: 12px;
            overflow: hidden;
            border: 1px solid rgba(245, 158, 11, 0.3);
            background: linear-gradient(135deg, rgba(245, 158, 11, 0.1), rgba(239, 68, 68, 0.04));
            backdrop-filter: blur(10px);
            transform: translateZ(0); 
            -webkit-backdrop-filter: blur(10px);
            box-shadow: 0 4px 14px rgba(245, 158, 11, 0.1), inset 0 1px 1px rgba(255,255,255,0.3);
            animation: courseBannerIn 0.35s cubic-bezier(0.34, 1.36, 0.64, 1);
        }
        @keyframes courseBannerIn {
            from { opacity: 0; transform: translateY(-6px); }
            to { opacity: 1; transform: translateY(0); }
        }
        .dark-mode #courseReminderBanner {
            background: linear-gradient(135deg, rgba(251, 191, 36, 0.1), rgba(239, 68, 68, 0.06));
            border-color: rgba(251, 191, 36, 0.25);
        }
        .course-reminder-head {
            display: flex;
            align-items: center;
            gap: 8px;
            padding: 9px 12px;
        }
        .course-reminder-icon {
