        .course-reminder-dismiss:hover { background: rgba(0,0,0,0.08); color: var(--text-dark); }
        .course-reminder-body {
            padding: 0 12px 10px;
        }
        .course-reminder-item {
            display: flex;
            align-items: center;
            gap: 8px;
            padding: 4px 0;
            font-size: 0.76rem;
        }
        .course-reminder-item-dot {
