        /* ============ SKILLS GLOBAL SEARCH ============ */
        .skills-search-wrap {
            position: relative;
            max-width: 640px;
            margin: 0 auto 20px;
            z-index: 60;
        }
        .skills-search-box {
            display: flex;
            align-items: center;
            gap: 10px;
            background: var(--bg-white);
            border: 1.5px solid var(--border-color);
            border-radius: 999px;
            padding: 11px 18px;
            box-shadow: var(--shadow-sm);
            transition: var(--transition);
        }
        .skills-search-box:focus-within {
            border-color: var(--primary);
            box-shadow: 0 0 0 4px rgba(var(--primary-rgb), 0.14), var(--shadow-md);
        }
        .skills-search-icon {
            color: var(--text-muted);
            font-size: 0.95rem;
            flex-shrink: 0;
        }
        .skills-search-box:focus-within .skills-search-icon { color: var(--primary); }
        .skills-search-input {
            flex: 1;
            min-width: 0;
            border: none;
            outline: none;
            background: transparent;
            font-size: 0.95rem;
            color: var(--text-dark);
        }
        .skills-search-input::placeholder { color: var(--text-muted); opacity: 0.85; }
        .skills-search-clear {
            display: flex;
            align-items: center;
            justify-content: center;
            width: 24px;
            height: 24px;
            flex-shrink: 0;
            border: none;
            border-radius: 50%;
            background: var(--bg-light);
            color: var(--text-muted);
            cursor: pointer;
            transition: var(--transition);
        }
        .skills-search-clear:hover { background: var(--primary-light); color: var(--primary-dark); }

        .skills-search-results {
            display: none;
            position: absolute;
            top: calc(100% + 8px);
            left: 0;
            right: 0;
            max-height: 440px;
            overflow-y: auto;
            background: var(--bg-white);
            border: 1px solid var(--border-color);
            border-radius: var(--radius-lg);
            box-shadow: var(--shadow-lg);
            padding: 8px;
        }
        .skills-search-results.open {
            display: block;
            animation: skillsSearchFadeIn 0.16s ease;
        }
        @keyframes skillsSearchFadeIn {
            from { opacity: 0; transform: translateY(-4px); }
            to   { opacity: 1; transform: translateY(0); }
        }
        .skills-search-summary {
            font-size: 0.75rem;
            color: var(--text-muted);
            font-weight: 600;
            padding: 4px 10px 8px;
        }
        .skills-search-empty {
            padding: 24px 14px;
            text-align: center;
            color: var(--text-muted);
            font-size: 0.9rem;
        }
        .ssr-group + .ssr-group {
            margin-top: 6px;
            border-top: 1px dashed var(--border-color);
            padding-top: 6px;
        }
        .ssr-group-header {
            display: flex;
            align-items: center;
            gap: 8px;
            padding: 6px 8px;
            font-size: 0.76rem;
            font-weight: 700;
            color: var(--text-muted);
            text-transform: uppercase;
            letter-spacing: 0.02em;
        }
        .ssr-career-dot {
            width: 9px;
            height: 9px;
            border-radius: 50%;
            flex-shrink: 0;
            background: var(--primary);
        }
        .ssr-career-dot[data-career="pe"] { background: var(--pe-color); }
        .ssr-career-dot[data-career="ib"] { background: var(--ib-color); }
        .ssr-career-dot[data-career="hf"] { background: var(--hf-color); }
        .ssr-career-dot[data-career="sc"] { background: var(--sc-color); }
        .ssr-career-dot[data-career="english"] { background: #d4a800; }
        .ssr-career-dot[data-career="fintech"] { background: #0aa8a0; }
        .ssr-career-dot[data-career="chinese"] { background: #00a68f; }
        .ssr-career-dot[data-career="german"] { background: #d4a017; }
        .ssr-career-dot[data-career="tools"] { background: var(--tools-color); }
        .ssr-career-dot[data-career="cfa1"] { background: #00a862; }
        .ssr-career-dot[data-career="acca"] { background: var(--acca-color); }
        .ssr-career-dot[data-career="china"] { background: var(--china-color); }
        .ssr-career-dot[data-career="quant"] { background: var(--quant-color); }
        .ssr-career-dot[data-career="analyst"] { background: var(--analyst-color); }

        .ssr-career-name { flex: 1; color: var(--text-dark); }
        .ssr-career-count {
            background: var(--primary-light);
            color: var(--primary-dark);
            font-size: 0.7rem;
            font-weight: 700;
            padding: 1px 8px;
            border-radius: 999px;
        }
        .ssr-group-items { display: flex; flex-direction: column; }
        .ssr-item {
            padding: 8px 10px;
            border-radius: var(--radius-md);
            cursor: pointer;
            transition: var(--transition);
        }
        .ssr-item:hover { background: var(--primary-light); }
        .ssr-item-name { font-size: 0.88rem; color: var(--text-dark); line-height: 1.35; }
        .ssr-item-path {
            margin-top: 2px;
            font-size: 0.74rem;
            color: var(--text-muted);
            display: flex;
            align-items: center;
            gap: 5px;
        }
        .ssr-mark {
            background: rgba(var(--primary-rgb), 0.28);
            color: var(--primary-dark);
            border-radius: 3px;
            padding: 0 1px;
            font-weight: 700;
        }

        /* Flash highlight when jumping to a matched skill from search */
        .skill-item.skill-highlight-flash {
            animation: skillHighlightPulse 2s ease;
            border-radius: var(--radius-md);
        }
        /* Same flash, for jumping to a course from a Notes Vault course pill */
        .course-item.course-highlight-flash {
            animation: skillHighlightPulse 2s ease;
            border-radius: var(--radius-lg);
        }
        /* Same flash, for jumping to a resource from a Notes Vault resource pill */
        .resource-card.resource-highlight-flash {
            animation: skillHighlightPulse 2s ease;
            border-radius: var(--radius-lg);
        }
        /* Same flash, for jumping to an Investment Analysis from a Notes Vault analysis pill */
        .ia-card.analysis-highlight-flash {
            animation: skillHighlightPulse 2s ease;
            border-radius: var(--radius-lg);
        }
        /* Same flash, for jumping to a Deal Diary entry from a Notes Vault deal pill */
        .dd-card.deal-highlight-flash {
            animation: skillHighlightPulse 2s ease;
            border-radius: var(--radius-lg);
        }
        @keyframes skillHighlightPulse {
            0%   { box-shadow: 0 0 0 3px rgba(var(--primary-rgb), 0.55); background: var(--primary-light); }
            70%  { box-shadow: 0 0 0 3px rgba(var(--primary-rgb), 0.55); background: var(--primary-light); }
            100% { box-shadow: 0 0 0 0 rgba(var(--primary-rgb), 0); background: transparent; }
        }

        @media (max-width: 640px) {
            .skills-search-wrap { max-width: 100%; margin: 0 0 16px; }
            .skills-search-results { max-height: 60vh; }
        }
 
        
        @media (max-width: 1100px) {
            .main-content {
                grid-template-columns: minmax(0, 1fr);
            }
            .sidebar {
                grid-row: 1;
                position: relative;
                top: auto;
                max-height: none;
                overflow-y: visible;
            }
        }

        @media (max-width: 768px) {
            .career-grid {
                grid-template-columns: repeat(5, 1fr);
            }
            h1 {
                font-size: 2rem;
            }
            .skill-item {
                flex-direction: column;
                align-items: flex-start;
            }
            .skill-controls {
                width: 100%;
                justify-content: flex-end;
            }
        }


        @media (max-width: 480px) {
            .career-grid {
                grid-template-columns: repeat(5, 1fr);
            }
            .progress-header {
                flex-direction: column;
                align-items: flex-start;
            }
        }

