        /* --- GOAL MANAGEMENT --- */

        .goal-add-btn {
            width: 100%;
            padding: 14px;
            background: rgba(219, 39, 119, 0.08); 
            color: var(--text-dark); 
            border: 2px solid rgba(219, 39, 119, 0.3);
