            box-shadow: 0 6px 16px rgba(244, 114, 182, 0.3);
        }

        .goal-progress-summary {
            background: linear-gradient(150deg, #fdf5f9 0%, #fdf1f7 55%, #faf1ff 100%);
            border-radius: var(--radius-lg);
            padding: 20px;
            margin: 15px 0;
            box-shadow: 0 3px 14px rgba(219,39,119,0.07);
            border: 1px solid rgba(219, 113, 175, 0.22);
            text-align: center;
            position: relative;
            overflow: hidden;
        }

        .dark-mode .goal-progress-summary {
            background: linear-gradient(150deg, #241823 0%, #2d1c2b 55%, #221722 100%);
            border-color: rgba(244,114,182,0.22);
        }

        .goal-progress-title {
            font-size: 1rem;
            font-weight: 600;
            color: var(--text-dark);
            margin-bottom: 10px;
            font-family: 'Segoe UI', sans-serif;
