        /* Small "copy AI prompt" icon in the Add Book header */
        .book-ai-copy {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            width: 26px;
            height: 26px;
            margin-left: 8px;
            padding: 0;
            vertical-align: middle;
            background: transparent;
            border: 1px solid var(--border-color);
            border-radius: 8px;
            color: var(--text-muted);
            cursor: pointer;
            transition: color .2s, border-color .2s, background .2s, transform .15s;
        }
        .book-ai-copy svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
        .book-ai-copy .ic-done { display: none; }
        .book-ai-copy:hover, .book-ai-copy:focus-visible { color: #db2777; border-color: #db2777; background: rgba(219, 39, 119, .08); }
        .book-ai-copy:active { transform: scale(.92); }
        .book-ai-copy.is-copied { color: #16a34a; border-color: #16a34a; background: rgba(22, 163, 74, .1); }
        .book-ai-copy.is-copied .ic-copy { display: none; }
        .book-ai-copy.is-copied .ic-done { display: block; }
        .dark-mode .book-ai-copy:hover, .dark-mode .book-ai-copy:focus-visible { color: #f472b6; border-color: #f472b6; background: rgba(244, 114, 182, .12); }
        .dark-mode .book-ai-copy.is-copied { color: #4ade80; border-color: #4ade80; }

