        /* ═══════════════════════════════════════════════════════════ */

        /* ═══════════════════════════════════════════════════════════
           YOUR PROGRESS
           ═══════════════════════════════════════════════════════════ */

        /* ═══════════════════════════════════════════════════════════
           "YOUR PROGRESS" CARD — upgraded visuals (v2)
           ═══════════════════════════════════════════════════════════ */
        @keyframes yprogCardIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
        @keyframes yprogBorderGlow {
            0%, 100% { box-shadow: 0 4px 24px rgba(219, 39, 119, 0.10), var(--shadow-md), 0 0 0 1px rgba(236,72,153,0.10); }
            50% { box-shadow: 0 4px 30px rgba(219, 39, 119, 0.20), var(--shadow-md), 0 0 0 1px rgba(236,72,153,0.22); }
        }
        @keyframes yprogSparkleDrift {
            0% { background-position: 0% 0%, 100% 100%, 40% 60%; }
            100% { background-position: 30% 20%, 70% 80%, 60% 30%; }
        }
        @keyframes yprogSheenSweep {
            0% { transform: translateX(-120%) rotate(8deg); }
            55%, 100% { transform: translateX(220%) rotate(8deg); }
        }
        @keyframes yprogIconRingSpin { to { transform: rotate(360deg); } }
        @keyframes yprogFlicker {
            0%, 100% { transform: scale(1) rotate(0deg); filter: brightness(1); }
            25% { transform: scale(1.08) rotate(-4deg); filter: brightness(1.15); }
            50% { transform: scale(0.97) rotate(3deg); filter: brightness(0.95); }
            75% { transform: scale(1.05) rotate(-2deg); filter: brightness(1.1); }
        }
        @keyframes yprogXpSheen { 0% { transform: translateX(-60%) skewX(-12deg); } 100% { transform: translateX(220%) skewX(-12deg); } }
        @keyframes yprogXpGlowPulse {
            0%, 100% { box-shadow: 0 0 6px rgba(219, 39, 119, 0.35), 0 1px 2px rgba(219, 39, 119, 0.25), inset 0 1px 0 rgba(255,255,255,0.5); }
            50% { box-shadow: 0 0 14px rgba(219, 39, 119, 0.55), 0 1px 3px rgba(219, 39, 119, 0.35), inset 0 1px 0 rgba(255,255,255,0.6); }
        }
        @keyframes yprogTotalGradient { 0% { background-position: 0% 50%; } 100% { background-position: 200% 50%; } }
        @keyframes yprogBadgeIn { from { opacity: 0; transform: translateY(6px) scale(0.92); } to { opacity: 1; transform: translateY(0) scale(1); } }
        @keyframes yprogTrendPulse { 0%, 100% { transform: scale(1); } 50% { transform: scale(1.05); } }

        #yourProgressCard {
            background: linear-gradient(135deg, #fdf5f9 0%, #fdf1f7 50%, #f9a8d422 100%) !important;
            backdrop-filter: none !important;
            border-radius: 20px;
            border: 1px solid rgba(236, 72, 153, 0.28);
            box-shadow: 0 4px 24px rgba(219, 39, 119, 0.10), var(--shadow-md);
            position: relative;
            overflow: hidden;
            animation: yprogCardIn 0.5s cubic-bezier(.2,.8,.2,1), yprogBorderGlow 6s ease-in-out infinite 0.5s;
            transition: transform 0.35s cubic-bezier(.2,.8,.2,1), box-shadow 0.35s ease, border-color 0.35s ease;
        }
        #yourProgressCard::before {
            content: '📊';
            position: absolute;
            right: -10px; top: -10px;
            font-size: 5rem;
            opacity: 0.06;
            pointer-events: none;
            transform: rotate(20deg);
            transition: transform 0.6s ease, opacity 0.6s ease;
        }
        /* Soft drifting sparkle field, purely decorative */
        #yourProgressCard::after {
            content: '';
            position: absolute;
            inset: 0;
            pointer-events: none;
            background-image:
                radial-gradient(circle, rgba(236,72,153,0.55) 0 1.5px, transparent 1.6px),
                radial-gradient(circle, rgba(246,173,85,0.5) 0 1.5px, transparent 1.6px),
                radial-gradient(circle, rgba(201, 168, 217,0.45) 0 1.5px, transparent 1.6px);
            background-size: 140px 140px, 180px 180px, 160px 160px;
            background-repeat: repeat;
            opacity: 0.35;
            animation: yprogSparkleDrift 14s ease-in-out infinite alternate;
            mix-blend-mode: multiply;
        }
        #yourProgressCard:hover {
            transform: translateY(-3px);
            border-color: rgba(236, 72, 153, 0.4);
            box-shadow: 0 18px 40px rgba(219, 39, 119, 0.16), inset 0 1px 1px rgba(255,255,255,0.7);
        }
        #yourProgressCard:hover::before { transform: rotate(8deg) scale(1.08); opacity: 0.09; }
        body.dark-mode #yourProgressCard {
            background: linear-gradient(135deg, #241823 0%, #2d1c2b 60%, #221722 100%) !important;
            border: 1px solid rgba(236, 72, 153, 0.28);
            box-shadow: 0 4px 24px rgba(244,114,182,0.10), var(--shadow-md);
        }
        body.dark-mode #yourProgressCard::after { mix-blend-mode: screen; opacity: 0.22; }
        body.dark-mode #yourProgressCard:hover {
            border-color: rgba(236, 72, 153, 0.45);
            box-shadow: 0 18px 40px rgba(244,114,182,0.18), inset 0 1px 1px rgba(255,255,255,0.05);
        }

        /* Header strip — rose/gold instead of the site-wide blue */
        #yourProgressCard > .sidebar-title {
            background: linear-gradient(135deg, rgba(219,39,119,0.10), rgba(217,164,6,0.07));
        }
        #yourProgressCard > .sidebar-title::after {
            background: linear-gradient(90deg, transparent, #db2777, transparent);
        }
        #yourProgressCard > .sidebar-title svg {
            transition: transform 0.4s cubic-bezier(.34,1.56,.64,1), filter 0.4s ease;
        }
        #yourProgressCard > .sidebar-title:hover {
            color: #db2777;
            filter: drop-shadow(0 4px 8px rgba(219, 39, 119, 0.18));
        }
        #yourProgressCard > .sidebar-title:hover svg {
            transform: scale(1.2) rotate(-8deg);
            filter: drop-shadow(0 0 6px rgba(219, 39, 119, 0.5));
        }
        body.dark-mode #yourProgressCard > .sidebar-title:hover {
            color: #f472b6;
            text-shadow: 0 0 10px rgba(244, 114, 182, 0.35);
        }

        /* ── Hero stats block ── */
        #yourProgressCard .gamification-stats {
            background: linear-gradient(150deg, #fdf1f7 0%, #f7e7fb 55%, #f1eaff 100%);
            background-size: auto;
            animation: none;
            color: #55265a;
            padding: 14px 14px;
            border-radius: 16px;
            border: 1px solid rgba(219, 113, 175, 0.25);
            box-shadow: 0 8px 22px rgba(219, 39, 119, 0.10), inset 0 1px 1px rgba(255,255,255,0.9);
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 7px 8px;
            margin-bottom: 0;
            text-align: center;
            position: relative;
            overflow: hidden;
        }
        #yourProgressCard .gamification-stats::before {
            content: '';
            position: absolute;
            top: -30%;
            right: -20%;
            width: 70%;
            height: 70%;
            background: radial-gradient(circle, rgba(255,255,255,0.55) 0%, transparent 70%);
            animation: none;
            pointer-events: none;
        }
        /* Slow diagonal light sweep across the whole hero panel */
        #yourProgressCard .gamification-stats::after {
            content: '';
            position: absolute;
            top: -50%;
            left: 0;
            width: 35%;
            height: 200%;
            background: linear-gradient(90deg, transparent, rgba(255,255,255,0.55), transparent);
            animation: yprogSheenSweep 7s ease-in-out infinite;
            pointer-events: none;
        }
        body.dark-mode #yourProgressCard .gamification-stats {
            background: linear-gradient(150deg, #2a1a33 0%, #341f42 55%, #2a2040 100%);
            color: #f7e3f0;
            border-color: rgba(236, 72, 153, 0.28);
            box-shadow: 0 8px 24px rgba(0,0,0,0.35), inset 0 1px 1px rgba(255,255,255,0.05);
        }
        body.dark-mode #yourProgressCard .gamification-stats::after {
            background: linear-gradient(90deg, transparent, rgba(255,255,255,0.10), transparent);
        }

        /* Level + Points sit side by side as soft pill stats */
        #yourProgressCard .level-container,
        #yourProgressCard .points-container {
            grid-column: span 1;
            background: rgba(255,255,255,0.55);
            border-radius: 13px;
            padding: 8px 6px;
            margin: 0;
            flex-direction: column;
            gap: 3px;
            font-size: 0.95rem;
            font-weight: 600;
            text-shadow: none;
            box-shadow: inset 0 0 0 1px rgba(219,113,175,0.15);
            transition: transform 0.28s cubic-bezier(.2,.8,.2,1), box-shadow 0.28s ease;
            position: relative;
        }
        #yourProgressCard .level-container:hover,
        #yourProgressCard .points-container:hover {
            transform: translateY(-3px) scale(1.03);
            box-shadow: inset 0 0 0 1px rgba(219,113,175,0.35), 0 10px 20px rgba(219,39,119,0.16);
            text-shadow: none;
        }
        body.dark-mode #yourProgressCard .level-container,
        body.dark-mode #yourProgressCard .points-container {
            background: rgba(255,255,255,0.06);
            box-shadow: inset 0 0 0 1px rgba(236,72,153,0.2);
        }

        #yourProgressCard .level-icon,
        #yourProgressCard .points-icon,
        #yourProgressCard .streak-icon {
            font-size: 1rem;
            width: 28px;
            height: 28px;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            border-radius: 50%;
            color: #fff;
            filter: none;
            animation: none;
            box-shadow: 0 3px 8px rgba(219, 39, 119, 0.25);
            position: relative;
            z-index: 1;
            transition: transform 0.35s cubic-bezier(.34,1.56,.64,1);
        }
        /* Spinning dashed halo behind each stat icon */
        #yourProgressCard .level-icon::before,
        #yourProgressCard .points-icon::before,
        #yourProgressCard .streak-icon::before {
            content: '';
            position: absolute;
            inset: -4px;
            border-radius: 50%;
            border: 1.5px dashed currentColor;
            opacity: 0.35;
            z-index: -1;
            animation: yprogIconRingSpin 10s linear infinite;
        }
        #yourProgressCard .level-container:hover .level-icon,
        #yourProgressCard .points-container:hover .points-icon,
        #yourProgressCard .streak-container:hover .streak-icon {
            transform: scale(1.15) rotate(-6deg);
        }
        #yourProgressCard .level-icon { background: linear-gradient(135deg, #f6ad55, #db9500); color: #f6ad55; }
        #yourProgressCard .points-icon { background: linear-gradient(135deg, #f9a8d4, #db2777); color: #db2777; }
        #yourProgressCard .streak-icon { background: linear-gradient(135deg, #fda4af, #f97316); color: #f97316; animation: yprogFlicker 3.2s ease-in-out infinite; }
        #yourProgressCard .level-icon i,
        #yourProgressCard .points-icon i,
        #yourProgressCard .streak-icon i { color: #fff; }

        #yourProgressCard .level-text,
        #yourProgressCard .points-text,
        #yourProgressCard .streak-text {
            font-size: 0.92rem;
            font-weight: 700;
            color: #55265a;
            text-shadow: none;
        }
        body.dark-mode #yourProgressCard .level-text,
        body.dark-mode #yourProgressCard .points-text,
        body.dark-mode #yourProgressCard .streak-text {
            color: #f7e3f0;
            text-shadow: none;
        }

        /* XP bar spans the full width beneath Level/Points */
        #yourProgressCard .xp-bar-track {
            grid-column: 1 / -1;
            position: relative;
            height: 11px;
            margin: 5px 0 1px;
            border-radius: 999px;
            background: linear-gradient(180deg, rgba(120, 40, 90, 0.10), rgba(255,255,255,0.5));
            border: 1px solid rgba(219, 113, 175, 0.22);
            box-shadow: inset 0 2px 4px rgba(85, 38, 90, 0.16), inset 0 -1px 0 rgba(255,255,255,0.55);
            overflow: hidden;
        }
        #yourProgressCard .xp-bar-fill {
            position: relative;
            height: 100%;
            min-width: 11px;
            border-radius: 999px;
            background: linear-gradient(90deg, #fbbf24 0%, #f6ad55 22%, #ec4899 60%, #db2777 100%);
            box-shadow: 0 0 6px rgba(219, 39, 119, 0.35), 0 1px 2px rgba(219, 39, 119, 0.25), inset 0 1px 0 rgba(255,255,255,0.5);
            animation: yprogXpGlowPulse 3s ease-in-out infinite;
            overflow: hidden;
            transition: width 0.7s cubic-bezier(.22,.9,.28,1);
        }
        /* Soft diagonal sheen gliding through the filled portion only */
        #yourProgressCard .xp-bar-fill::before {
            content: '';
            position: absolute;
            top: -40%;
            left: 0;
            width: 35%;
            height: 180%;
            background: linear-gradient(90deg, transparent, rgba(255,255,255,0.65), transparent);
            animation: yprogXpSheen 3.4s ease-in-out infinite;
            pointer-events: none;
        }
        /* Bright leading edge, like a little glowing spark at the current XP point */
        #yourProgressCard .xp-bar-fill::after {
            content: '';
            position: absolute;
            top: 0; right: 0;
            width: 40%;
            height: 100%;
            background: linear-gradient(90deg, transparent, rgba(255,255,255,0.5));
            pointer-events: none;
