            background: linear-gradient(180deg, rgba(0,0,0,0.35), rgba(255,255,255,0.04));
            border-color: rgba(236, 72, 153, 0.22);
            box-shadow: inset 0 2px 4px rgba(0,0,0,0.4), inset 0 -1px 0 rgba(255,255,255,0.05);
