        /* ═══════════════════════════════════════════════════════════
           YOUR PROGRESS — v3 calm & clear overrides
           Goals: fewer always-on animations (ADHD-friendly), higher
           contrast, bigger small-text, clearer hierarchy, keyboard +
           screen-reader support. Placed after v2 so it wins the cascade.
           ═══════════════════════════════════════════════════════════ */

        /* Visually hidden, still read by screen readers */
        .yprog-sr {
            position: absolute !important;
            width: 1px; height: 1px;
            margin: -1px; padding: 0;
            overflow: hidden;
            clip: rect(0 0 0 0);
            white-space: nowrap;
            border: 0;
        }

        /* ── 1. Stop the perpetual motion. Keep one-shot entrances only. ── */
        #yourProgressCard {
            animation: yprogCardIn 0.4s cubic-bezier(.2,.8,.2,1) both !important;
            box-shadow: 0 4px 18px rgba(219, 39, 119, 0.10), var(--shadow-md);
        }
        #yourProgressCard::after { content: none !important; animation: none !important; }
        #yourProgressCard .gamification-stats::after { content: none !important; animation: none !important; }
        #yourProgressCard .level-icon::before,
        #yourProgressCard .points-icon::before,
        #yourProgressCard .streak-icon::before { animation: none !important; }
        #yourProgressCard .streak-icon { animation: none !important; }
        #yourProgressCard .streak-container:hover .streak-icon { animation: yprogFlicker 1.2s ease-in-out 1; }
        #yourProgressCard .xp-bar-fill { animation: none !important; }
        #yourProgressCard .xp-bar-fill::before { content: none !important; animation: none !important; }
        #yourProgressCard .meme-caption {
            animation: none !important;
            background: none !important;
            -webkit-text-fill-color: currentColor !important;
            color: #9d2867;
            box-shadow: none !important;
        }
        body.dark-mode #yourProgressCard .meme-caption { color: #f5c2dd; }

        /* Hover shouldn't make a data card jump around under the cursor. */
        #yourProgressCard:hover,
        #yourProgressCard .chart-container:hover,
        #yourProgressCard .level-container:hover,
        #yourProgressCard .points-container:hover,
        #yourProgressCard .streak-container:hover,
        #yourProgressCard .meme-widget:hover .meme-image-container {
            transform: none !important;
        }
        #yourProgressCard .level-container:hover .level-icon,
        #yourProgressCard .points-container:hover .points-icon,
        #yourProgressCard .streak-container:hover .streak-icon { transform: none; }

        /* ── 2. Hierarchy: the one number that matters is solid, big and readable ── */
        #yourProgressCard .yprog-hours-value,
        body.dark-mode #yourProgressCard .yprog-hours-value {
            background: none !important;
            animation: none !important;
            -webkit-text-fill-color: currentColor !important;
            color: #9d2867;
            font-size: 2rem;
            font-variant-numeric: tabular-nums;
            line-height: 1.15;
        }
        body.dark-mode #yourProgressCard .yprog-hours-value { color: #f9d0e6; }

        /* ── 3. Contrast + minimum text size (>= 11–12px) ── */
        #yourProgressCard .yprog-hours-caption,
        #yourProgressCard .yprog-hours-label,
        #yourProgressCard .xp-bar-label,
        #yourProgressCard .streak-best {
            color: rgba(85, 38, 90, 0.8);
            font-size: 0.74rem;
        }
        body.dark-mode #yourProgressCard .yprog-hours-caption,
        body.dark-mode #yourProgressCard .yprog-hours-label,
        body.dark-mode #yourProgressCard .xp-bar-label,
        body.dark-mode #yourProgressCard .streak-best { color: rgba(247, 227, 240, 0.82); }
        #yourProgressCard .yprog-stat-label { font-size: 0.74rem; }
        #yourProgressCard .yprog-stat-caption { font-size: 0.72rem; }
        #yourProgressCard .skills-stats-list-title { font-size: 0.76rem; }
        #yourProgressCard .skills-stats-row { font-size: 0.86rem; }
        #yourProgressCard .skills-stats-pct { font-size: 0.78rem; width: 38px; }
        #yourProgressCard .yprog-hours-num { font-size: 1.1rem; font-variant-numeric: tabular-nums; }
        #yourProgressCard .skills-stats-bar-track { height: 8px; }
        #yourProgressCard .skills-stats-empty { font-size: 0.84rem; }
        #yourProgressCard .skills-stats-list { max-height: 300px; }

        /* Section labels give the long card a scannable structure */
        #yourProgressCard .yprog-section-label {
            margin: 18px 2px 2px;
            font-size: 0.76rem;
            font-weight: 800;
            letter-spacing: 0.08em;
            text-transform: uppercase;
            color: #9d2867;
        }
        body.dark-mode #yourProgressCard .yprog-section-label { color: #f5c2dd; }

        /* ── 4. Streak nudge ── */
        #yourProgressCard .streak-hint {
            grid-column: 1 / -1;
            font-size: 0.78rem;
            font-weight: 600;
            line-height: 1.35;
            color: #92400e;
            background: rgba(251, 191, 36, 0.18);
            border: 1px solid rgba(217, 119, 6, 0.3);
            border-radius: 10px;
            padding: 6px 10px;
        }
        body.dark-mode #yourProgressCard .streak-hint {
            color: #fde68a;
            background: rgba(251, 191, 36, 0.12);
            border-color: rgba(251, 191, 36, 0.3);
        }
        #yourProgressCard .streak-hint[hidden] { display: none; }

        /* ── 5. Level-up: the one moment that earns an animation (plays once) ── */
        @keyframes yprogLevelPop {
            0%   { transform: scale(1); box-shadow: inset 0 0 0 1px rgba(219,113,175,0.15), 0 0 0 0 rgba(219,39,119,0.45); }
            35%  { transform: scale(1.1); box-shadow: inset 0 0 0 1px rgba(219,113,175,0.4), 0 0 0 10px rgba(219,39,119,0); }
            100% { transform: scale(1); box-shadow: inset 0 0 0 1px rgba(219,113,175,0.15), 0 0 0 0 rgba(219,39,119,0); }
        }
        #yourProgressCard .level-container.yprog-levelup { animation: yprogLevelPop 0.9s ease-out 1; }

        /* ── 6. Weekly goal ── */
        #yourProgressCard .yprog-goal {
            margin-top: 12px;
            padding-top: 12px;
            border-top: 1px dashed rgba(219, 113, 175, 0.28);
