            font-size: 0.78rem;
        }
        #yourProgressCard .yprog-goal-edit:hover { background: rgba(219, 39, 119, 0.08); }
        body.dark-mode #yourProgressCard .yprog-goal-edit { color: #f5c2dd; border-color: rgba(236,72,153,0.4); }
        #yourProgressCard .yprog-goal-input {
            width: 72px;
            min-height: 32px;
            padding: 2px 8px;
            border: 1.5px solid #db2777;
            border-radius: 8px;
            background: #fff;
            color: #55265a;
            font: inherit;
            font-weight: 700;
        }
        body.dark-mode #yourProgressCard .yprog-goal-input { background: #2a1a33; color: #f7e3f0; }
        #yourProgressCard .yprog-goal-track {
            height: 10px;
            border-radius: 999px;
            background: rgba(120, 40, 90, 0.12);
            overflow: hidden;
        }
        body.dark-mode #yourProgressCard .yprog-goal-track { background: rgba(0,0,0,0.35); }
        #yourProgressCard .yprog-goal-fill {
            height: 100%;
            border-radius: 999px;
            background: linear-gradient(90deg, #ec4899, #db2777);
            transition: width 0.6s cubic-bezier(.22,.9,.28,1);
        }
        #yourProgressCard .yprog-goal-fill.is-done { background: linear-gradient(90deg, #22c55e, #16a34a); }
        #yourProgressCard .yprog-goal-hint {
            margin-top: 6px;
            font-size: 0.76rem;
            color: rgba(85, 38, 90, 0.8);
        }
        body.dark-mode #yourProgressCard .yprog-goal-hint { color: rgba(247, 227, 240, 0.82); }

        /* ── 7. Empty-state call to action ── */
        #yourProgressCard .yprog-empty-cta {
            display: flex;
            flex-wrap: wrap;
            align-items: center;
            justify-content: space-between;
            gap: 8px 12px;
            margin: 0 0 12px;
