        /* ── 9. Mood break (meme) — collapsed by default so it never interrupts the data ── */
        #yourProgressCard .yprog-fun {
            margin-top: 14px;
            border-top: 1px dashed rgba(219, 113, 175, 0.3);
            padding-top: 10px;
        }
        #yourProgressCard .yprog-fun > summary {
            cursor: pointer;
            min-height: 36px;
            display: flex;
            align-items: center;
            font-size: 0.78rem;
            font-weight: 800;
            letter-spacing: 0.08em;
            text-transform: uppercase;
            color: #9d2867;
