        #yourProgressCard .yprog-fun[open] > summary { margin-bottom: 8px; }

        /* ── 10. Keyboard focus + touch targets ── */
        #yourProgressCard button:focus-visible,
        #yourProgressCard summary:focus-visible,
        #yourProgressCard input:focus-visible,
        #yourProgressCard [onclick]:focus-visible {
            outline: 3px solid #7c3aed;
            outline-offset: 2px;
            border-radius: 8px;
        }
        body.dark-mode #yourProgressCard button:focus-visible,
        body.dark-mode #yourProgressCard summary:focus-visible,
        body.dark-mode #yourProgressCard input:focus-visible { outline-color: #c4b5fd; }
        #yourProgressCard .badges-title { min-height: 40px; }

        /* ── 11. Respect "reduce motion" for everything in the card ── */
        @media (prefers-reduced-motion: reduce) {
            #yourProgressCard,
            #yourProgressCard *,
            #yourProgressCard *::before,
            #yourProgressCard *::after {
                animation: none !important;
                transition: none !important;
