/* ═══ [2/38] <style> — originally at index.html line 19693 ═══ */
/* ── Overlay ── */
#calendarModal {
    display:none; position:fixed; inset:0;
    background:rgba(0,0,0,.55); z-index:10500;
    align-items:center; justify-content:center; padding:12px;
    backdrop-filter:blur(4px);
    transform: translateZ(0); 
}
#calendarModal.open { display:flex; }

/* ── Box ── */
#calendarBox {
    background:var(--bg-white); border-radius:20px;
    width:100%; max-width:880px; max-height:92vh;
    display:flex; flex-direction:column;
    box-shadow:0 24px 64px rgba(0,0,0,.28);
    overflow:hidden;
    animation:calSlideIn .3s cubic-bezier(.34,1.36,.64,1);
}
@keyframes calSlideIn {
    from{opacity:0;transform:translateY(22px) scale(.96);}
    to  {opacity:1;transform:translateY(0)    scale(1);}
}

/* ── Header ── */
#calHeader {
    display:flex; align-items:center; justify-content:space-between;
    padding:16px 22px 14px; border-bottom:1px solid var(--border-color);
    flex-shrink:0; flex-wrap:wrap; gap:10px;
}
.cal-title { font-size:1.2rem; font-weight:700; color:var(--text-dark); display:flex; align-items:center; gap:8px; }
.cal-nav { display:flex; align-items:center; gap:8px; flex-wrap:wrap; }
.cal-nav-btn {
    background:var(--bg-light); border:1px solid var(--border-color);
    border-radius:8px; padding:6px 12px; cursor:pointer;
    font-size:.85rem; font-weight:600; color:var(--text-dark);
    transition:all .15s;
}
.cal-nav-btn:hover { background:var(--primary); color:#fff; border-color:var(--primary); }
.cal-today-btn {
    background:linear-gradient(135deg,var(--primary),var(--theme-accent-3)); color:#fff;
    border:none; border-radius:8px; padding:6px 14px;
    font-size:.85rem; font-weight:700; cursor:pointer;
}
.cal-close-btn {
    background:none; border:none; font-size:1.4rem; cursor:pointer;
    color:var(--text-muted); line-height:1; padding:4px;
}
.cal-close-btn:hover { color:var(--text-dark); }

/* ── Tabs ── */
#calTabs {
    display:flex; padding:12px 22px 0; gap:8px;
    border-bottom:1px solid var(--border-color); flex-shrink:0;
}
.cal-tab {
    padding:8px 20px; border-radius:10px 10px 0 0;
    font-size:.88rem; font-weight:700; cursor:pointer;
    border:1px solid transparent; border-bottom:none;
    color:var(--text-muted); background:transparent; transition:all .15s;
}
.cal-tab.active {
    background:var(--bg-white); color:var(--primary);
    border-color:var(--border-color); border-bottom-color:var(--bg-white);
    margin-bottom:-1px;
}

/* ── Body ── */
#calBody { flex:1; overflow-y:auto; padding:18px 22px 22px; }

/* ── Legend ── */
.cal-legend {
    display:flex; gap:14px; flex-wrap:wrap;
    padding:10px 22px; background:var(--bg-light);
    border-bottom:1px solid var(--border-color);
    flex-shrink:0;
}
.cal-legend-item { display:flex; align-items:center; gap:5px; font-size:.75rem; color:var(--text-muted); }
.cal-legend-dot { width:10px; height:10px; border-radius:3px; flex-shrink:0; }

/* ── Day view ── */
.cal-day-grid {
    display:grid;
    grid-template-columns:52px 1fr;
    gap:0;
    position:relative;
}
.cal-hour-label {
    font-size:.72rem; color:var(--text-muted); text-align:right;
    padding-right:10px; line-height:1; position:relative; top:-7px;
    height:56px; display:flex; align-items:flex-start; justify-content:flex-end;
    padding-top:2px;
}
.cal-hour-row {
    border-top:1px solid var(--border-color); height:56px;
    position:relative; cursor:pointer; transition:background .12s;
}
.cal-hour-row:hover { background:rgba(99,102,241,.05); }
.cal-hour-row.now-row { border-top:2px solid #ef4444; }

/* ── Events ── */
.cal-event {
    position:absolute; left:3px; right:3px;
    border-radius:7px; padding:3px 7px;
    font-size:.75rem; font-weight:600; color:#fff;
    overflow:hidden; cursor:pointer; z-index:2;
    line-height:1.3;
    box-shadow:0 1px 4px rgba(0,0,0,.18);
    transition:transform .12s, box-shadow .12s;
}
.cal-event:hover { transform:scale(1.02); box-shadow:0 3px 10px rgba(0,0,0,.25); }
.cal-event-title { white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.cal-event-time  { font-size:.68rem; opacity:.85; }

/* ── Now line ── */
#calNowLine {
    position:absolute; left:52px; right:0;
    height:2px; background:#ef4444; z-index:5; pointer-events:none;
}
#calNowLine::before {
    content:''; position:absolute; left:-4px; top:-4px;
    width:10px; height:10px; border-radius:50%; background:#ef4444;
}

/* ── Free slot ── */
.cal-free-slot {
    position:absolute; left:3px; right:3px;
    background:rgba(16,185,129,.08); border:1.5px dashed rgba(16,185,129,.4);
    border-radius:7px; cursor:pointer; z-index:1;
    display:flex; align-items:center; justify-content:center;
    font-size:.72rem; color:#059669; font-weight:600;
    transition:all .15s;
}
.cal-free-slot:hover {
    background:rgba(16,185,129,.18);
    border-color:rgba(16,185,129,.7);
}

/* ── Week view ── */
.cal-week-grid {
    display:grid;
    grid-template-columns:44px repeat(7,1fr);
    border:1px solid var(--border-color);
    border-radius:12px; overflow:hidden;
}
.cal-week-header {
    display:contents;
}
.cal-week-col-head {
    padding:8px 4px; text-align:center;
    background:var(--bg-light); border-bottom:1px solid var(--border-color);
    border-right:1px solid var(--border-color);
    font-size:.78rem; font-weight:700; color:var(--text-dark);
}
.cal-week-col-head.today-col { background:rgba(var(--primary-rgb),.1); color:var(--primary); }
.cal-week-col-head.corner { background:var(--bg-light); }
.cal-week-row {
    display:contents;
}
.cal-week-hour-label {
    font-size:.68rem; color:var(--text-muted);
    padding:4px 6px 0 4px; text-align:right;
    border-right:1px solid var(--border-color);
    border-bottom:1px solid rgba(240, 215, 222,.5);
    height:40px; background:var(--bg-light);
    display:flex; align-items:flex-start; justify-content:flex-end;
}
.cal-week-cell {
    border-right:1px solid var(--border-color);
    border-bottom:1px solid rgba(240, 215, 222,.5);
    height:40px; position:relative; cursor:pointer;
    transition:background .12s;
}
.cal-week-cell:hover { background:rgba(99,102,241,.05); }
.cal-week-cell.today-col { background:rgba(99,102,241,.03); }
.cal-week-cell.past-cell { background:rgba(0,0,0,.02); }
.cal-week-event {
    position:absolute; inset:1px 2px;
    border-radius:4px; padding:1px 4px;
    font-size:.65rem; font-weight:700; color:#fff;
    overflow:hidden; white-space:nowrap; text-overflow:ellipsis;
    cursor:pointer; z-index:2;
}
.cal-week-free {
    position:absolute; inset:1px 2px;
    background:rgba(16,185,129,.12); border:1px dashed rgba(16,185,129,.35);
    border-radius:4px;
}

/* ── Quick-add slot modal ── */
#calSlotModal {
    display:none; position:fixed; inset:0;
    background:rgba(0,0,0,.5); z-index:11000;
    align-items:center; justify-content:center; padding:16px;
}
#calSlotModal.open { display:flex; }
.cal-slot-box {
    background:var(--bg-white); border-radius:16px;
    width:100%; max-width:380px;
    max-height:88vh;
    display:flex; flex-direction:column;
    box-shadow:0 20px 50px rgba(0,0,0,.25);
    animation:calSlideIn .25s ease;
    overflow:hidden;
}
.cal-slot-box-header {
    display:flex; align-items:center; justify-content:space-between;
    gap:12px; padding:20px 24px 12px; flex-shrink:0;
    border-bottom:1px solid var(--border-color);
}
.cal-slot-box-header h4 { margin:0; }
.cal-slot-close-x {
    flex-shrink:0; width:30px; height:30px; border-radius:8px;
    border:1px solid var(--border-color); background:var(--bg-light);
    color:var(--text-muted); font-size:1rem; line-height:1; cursor:pointer;
    display:flex; align-items:center; justify-content:center;
    transition:var(--transition);
}
.cal-slot-close-x:hover { background:#ef4444; border-color:#ef4444; color:#fff; }
.cal-slot-box-body {
    overflow-y:auto; padding:16px 24px 4px; flex:1 1 auto;
}
.cal-slot-box h4 { margin:0 0 16px; font-size:1.05rem; font-weight:700; color:var(--text-dark); }
.cal-slot-box label { display:block; font-size:.8rem; font-weight:600; color:var(--text-muted); margin-bottom:4px; }
.cal-slot-box input,
.cal-slot-box select,
.cal-slot-box textarea {
    width:100%; padding:9px 11px; border:1px solid var(--border-color);
    border-radius:8px; font-size:.9rem; background:var(--bg-light);
    color:var(--text-dark); margin-bottom:12px;
}
.cal-slot-actions { display:flex; gap:8px; flex-shrink:0; padding:14px 24px 20px; border-top:1px solid var(--border-color); }
.cal-slot-btn {
    flex:1; padding:10px 8px; background:transparent; border-radius:8px;
    font-weight:700; font-size:.85rem; cursor:pointer; text-align:center;
    white-space:nowrap; transition: background .15s ease, border-color .15s ease;
}
.cal-slot-btn-neutral {
    border:1.5px solid var(--border-color); color:var(--text-muted);
}
.cal-slot-btn-neutral:hover { background: var(--bg-light); }
.cal-slot-btn-danger {
    border:1.5px solid #ef4444; color:#ef4444;
}
.cal-slot-btn-danger:hover { background: rgba(239,68,68,.08); }
.cal-slot-btn-primary {
    border:1.5px solid var(--primary); color:var(--primary);
}
.cal-slot-btn-primary:hover { background: rgba(var(--primary-rgb),.1); }
.dark-mode .cal-slot-btn-neutral { color: var(--text-dark); }

/* ── 🌸 Sakura Mist: Delete-choice modal ── */
#calDeleteChoiceModal {
    display:none; position:fixed; inset:0;
    background:rgba(74,50,64,.45); z-index:11500;
    align-items:center; justify-content:center; padding:16px;
    backdrop-filter: blur(2px);
}
#calDeleteChoiceModal.open { display:flex; }
.cal-delete-box {
    background:var(--bg-white); border-radius:16px;
    width:100%; max-width:380px;
    box-shadow:0 20px 50px rgba(168,88,112,.28);
    animation:calSlideIn .25s ease;
    overflow:hidden;
    border:1px solid var(--theme-border-strong);
}
.cal-delete-box-header {
    display:flex; align-items:center; justify-content:space-between;
    gap:12px; padding:18px 22px 12px;
    border-bottom:1px solid var(--border-color);
}
.cal-delete-box-header h4 {
    margin:0; font-size:1.02rem; font-weight:700; color:var(--text-dark);
    display:flex; align-items:center; gap:8px;
}
.cal-delete-box-body { padding:16px 22px 4px; }
.cal-delete-event-name {
    font-size:1rem; font-weight:700; color:var(--primary-dark);
    margin:0 0 2px;
}
.cal-delete-event-meta {
    font-size:.8rem; color:var(--text-muted); margin:0 0 14px;
    text-transform:capitalize;
}
.cal-delete-hint {
    font-size:.78rem; color:var(--text-muted); margin:0 0 12px; line-height:1.5;
}
.cal-delete-option {
    width:100%; display:flex; align-items:flex-start; gap:10px;
    text-align:left; padding:12px 14px; margin-bottom:10px;
    background:var(--bg-light); border:1.5px solid var(--border-color);
    border-radius:12px; cursor:pointer; transition:var(--transition);
}
.cal-delete-option:last-child { margin-bottom:2px; }
.cal-delete-option:disabled { cursor:default; opacity:.85; }
.cal-delete-option:hover {
    border-color:var(--primary); background:var(--primary-light);
    transform:translateY(-1px); box-shadow:var(--shadow-sm);
}
.cal-delete-option-danger:hover {
    border-color:#e2637f; background:rgba(226,99,127,.10);
}
.cal-delete-option-icon { font-size:1.2rem; line-height:1.3; flex-shrink:0; }
.cal-delete-option-text { display:flex; flex-direction:column; gap:2px; }
.cal-delete-option-text strong { font-size:.88rem; color:var(--text-dark); }
.cal-delete-option-text small { font-size:.74rem; color:var(--text-muted); line-height:1.4; }
.cal-delete-confirm-btn {
    flex:1; padding:10px; border:none; border-radius:8px;
    background:linear-gradient(135deg,#e2637f,#c94f6c);
    color:#fff; font-weight:700; font-size:.9rem; cursor:pointer;
    transition:var(--transition);
}
.cal-delete-confirm-btn:hover { filter:brightness(1.06); box-shadow:var(--shadow-md); }

/* Visible focus ring on the delete-choice options — makes it obvious
   which button Enter/Space will trigger (defaults to the safe one). */
.cal-delete-option:focus-visible,
.cal-delete-confirm-btn:focus-visible,
#calDeleteCancelBtn:focus-visible {
    outline:2.5px solid var(--primary); outline-offset:2px;
}
.cal-delete-option-danger:focus-visible { outline-color:#e2637f; }

/* Brief shake on the "delete entire series" button when clicked, so the
   destructive action gets a half-second beat of visual warning before
   it actually fires (see CAL.confirmDeleteSeriesGuarded). */
@keyframes calDangerShake {
    10%, 90% { transform:translateX(-1px); }
    20%, 80% { transform:translateX(2px); }
    30%, 50%, 70% { transform:translateX(-4px); }
    40%, 60% { transform:translateX(4px); }
}
.cal-delete-option-danger.shaking {
    animation:calDangerShake .45s ease;
    border-color:#e2637f; background:rgba(226,99,127,.14);
    box-shadow:0 0 0 3px rgba(226,99,127,.18);
}

.dark-mode .cal-delete-box { background:var(--bg-white); border-color:var(--theme-border-strong); }
.dark-mode .cal-delete-option { background:rgba(255,255,255,.03); border-color:var(--border-color); }
.dark-mode .cal-delete-option:hover { background:rgba(var(--primary-rgb),.14); }
.dark-mode .cal-delete-option-danger:hover { background:rgba(226,99,127,.16); }

/* ── Dark mode patches ── */
.dark-mode #calendarBox { background:var(--bg-white); }
.dark-mode .cal-tab.active { background:var(--bg-white); border-color:var(--border-color); border-bottom-color:var(--bg-white); }
.dark-mode .cal-slot-box { background:var(--bg-white); }
.dark-mode .cal-week-grid { border-color:var(--border-color); }
.dark-mode .cal-week-col-head, .dark-mode .cal-week-hour-label { background:var(--bg-white); }
.dark-mode .cal-week-cell.past-cell { background:rgba(255,255,255,.02); }
.dark-mode .cal-hour-row:hover { background:rgba(var(--primary-rgb),.08); }

/* ── Responsive ── */
@media(max-width:640px){
    #calendarBox { border-radius:14px; }
    #calHeader { padding:12px 14px 10px; }
    #calBody    { padding:12px 14px 16px; }
    .cal-week-grid { grid-template-columns:32px repeat(7,1fr); }
    .cal-week-col-head { font-size:.65rem; padding:6px 2px; }
    .cal-week-hour-label { font-size:.6rem; padding:2px 3px 0; }
}

/* ── To-Do List (ABCDE priority + due dates) — v3 ── */
/* Accent chính đồng bộ theme hồng (sakura). Màu ABCDE là mã màu mức ưu tiên có
   chủ đích (đỏ=gấp nhất → xám=loại bỏ), giữ nguyên vì mang ý nghĩa riêng.
   Đỏ chỉ còn dùng cho hành động xoá (destructive) và quá hạn. */
.todo-wrap{padding:4px 2px 20px;}

/* stat chips row */
.todo-stats-row{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:14px;}
.todo-stat-chip{background:var(--bg-white);border:1px solid var(--border-color);border-radius:12px;padding:10px 8px;text-align:center;box-shadow:var(--shadow-sm);transition:transform .15s,box-shadow .15s;}
.todo-stat-chip:hover{transform:translateY(-2px);box-shadow:var(--shadow-md);}
.todo-stat-num{font-size:1.15rem;font-weight:800;line-height:1.1;}
.todo-stat-label{font-size:.62rem;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:.4px;margin-top:2px;}
.todo-stat-chip.is-overdue .todo-stat-num{color:#ef4444;}
.todo-stat-chip.is-today .todo-stat-num{color:#f97316;}
.todo-stat-chip.is-open .todo-stat-num{background:linear-gradient(135deg,#d17b96,#f472b6);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;}
.todo-stat-chip.is-done .todo-stat-num{color:#22c55e;}

/* progress bar */
.todo-progress-wrap{background:var(--bg-light);border-radius:14px;padding:14px 16px;margin-bottom:16px;border:1px solid var(--border-color);position:relative;overflow:hidden;}
.todo-progress-info{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:8px;}
.todo-progress-label{font-size:.78rem;font-weight:700;color:var(--text-muted);}
.todo-progress-pct{font-size:1.05rem;font-weight:800;background:linear-gradient(135deg,#d17b96,#f472b6);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;}
.todo-progress-bar{height:9px;border-radius:20px;background:var(--border-color);overflow:hidden;position:relative;}
.todo-progress-fill{height:100%;border-radius:20px;background:linear-gradient(90deg,#d17b96,#f472b6);transition:width .5s cubic-bezier(.4,0,.2,1);position:relative;}
.todo-progress-fill::after{content:'';position:absolute;inset:0;background:linear-gradient(90deg,transparent,rgba(255,255,255,.35),transparent);animation:todoShine 2.2s ease-in-out infinite;}
@keyframes todoShine{0%{transform:translateX(-100%);}100%{transform:translateX(100%);}}

/* add row */
.todo-add-row{display:flex;gap:8px;margin-bottom:10px;flex-wrap:wrap;}
.todo-add-input{flex:1;min-width:180px;padding:11px 14px;border:1.5px solid var(--border-color);border-radius:10px;font-size:.88rem;background:var(--bg-white);color:var(--text-dark);transition:border-color .2s,box-shadow .2s;}
.todo-add-input:focus{outline:none;border-color:#d17b96;box-shadow:0 0 0 3px rgba(219,113,175,.15);}
.todo-add-select{padding:11px 10px;border:1.5px solid var(--border-color);border-radius:10px;font-size:.85rem;background:var(--bg-white);color:var(--text-dark);cursor:pointer;transition:border-color .2s;}
.todo-add-select:focus{outline:none;border-color:#d17b96;}
.todo-add-due{padding:11px 10px;border:1.5px solid var(--border-color);border-radius:10px;font-size:.8rem;background:var(--bg-white);color:var(--text-dark);cursor:pointer;transition:border-color .2s;min-width:130px;}
.todo-add-due:focus{outline:none;border-color:#d17b96;}
.todo-add-btn{padding:11px 18px;background:linear-gradient(135deg,#d17b96,#a85870);color:#fff;border:none;border-radius:10px;font-size:.85rem;font-weight:700;cursor:pointer;white-space:nowrap;box-shadow:0 3px 10px rgba(219,113,175,.35);transition:transform .15s,box-shadow .15s,opacity .15s;}
.todo-add-btn:hover{transform:translateY(-2px);box-shadow:0 6px 16px rgba(219,113,175,.45);opacity:1;}
.todo-add-btn:active{transform:translateY(0);}

/* quick due-date chips shown under the add row */
.todo-quick-due{display:flex;gap:6px;flex-wrap:wrap;margin:0 0 12px;}
.todo-quick-due-btn{font-size:.68rem;font-weight:700;padding:5px 10px;border-radius:20px;border:1px solid var(--border-color);background:var(--bg-light);color:var(--text-muted);cursor:pointer;transition:all .15s;}
.todo-quick-due-btn:hover,.todo-quick-due-btn.active{background:#d17b96;border-color:#d17b96;color:#fff;}

/* filter chips */
.todo-filter-row{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:16px;}
.todo-filter-btn{font-size:.72rem;font-weight:700;padding:6px 12px;border-radius:20px;border:1.5px solid var(--border-color);background:var(--bg-white);color:var(--text-muted);cursor:pointer;transition:all .15s;display:flex;align-items:center;gap:5px;}
.todo-filter-btn:hover{border-color:#d17b96;color:#d17b96;}
.todo-filter-btn.active{background:linear-gradient(135deg,#d17b96,#a85870);border-color:#d17b96;color:#fff;box-shadow:0 3px 8px rgba(219,113,175,.3);}
.todo-filter-btn .fc-badge{font-size:.62rem;font-weight:800;background:rgba(0,0,0,.12);padding:1px 6px;border-radius:10px;}
.todo-filter-btn.active .fc-badge{background:rgba(255,255,255,.28);}

/* search + tag filter row */
.todo-search-row{display:flex;gap:8px;margin-bottom:10px;}
.todo-search-wrap{position:relative;flex:1;}
.todo-search-wrap i{position:absolute;left:12px;top:50%;transform:translateY(-50%);color:var(--text-muted);font-size:.8rem;pointer-events:none;}
.todo-search-input{width:100%;padding:10px 34px 10px 32px;border:1.5px solid var(--border-color);border-radius:10px;font-size:.85rem;background:var(--bg-white);color:var(--text-dark);transition:border-color .2s,box-shadow .2s;}
.todo-search-input:focus{outline:none;border-color:#d17b96;box-shadow:0 0 0 3px rgba(219,113,175,.15);}
.todo-search-clear{position:absolute;right:8px;top:50%;transform:translateY(-50%);background:none;border:none;color:var(--text-muted);cursor:pointer;font-size:.8rem;padding:4px;border-radius:6px;}
.todo-search-clear:hover{color:#ef4444;background:rgba(239,68,68,.1);}

.todo-tag-row{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:16px;align-items:center;}
.todo-tag-row-label{font-size:.68rem;font-weight:700;color:var(--text-muted);margin-right:2px;}
.todo-tag-chip{font-size:.7rem;font-weight:700;padding:4px 10px;border-radius:20px;border:1.5px solid transparent;cursor:pointer;transition:all .15s;display:inline-flex;align-items:center;gap:4px;}
.todo-tag-chip.active{box-shadow:0 2px 8px rgba(0,0,0,.15);transform:translateY(-1px);}

/* per-row tag pills */
.todo-tags-inline{display:flex;flex-wrap:wrap;gap:4px;}
.todo-tag-pill{font-size:.62rem;font-weight:700;padding:1px 8px;border-radius:20px;line-height:1.5;cursor:pointer;transition:transform .15s;}
.todo-tag-pill:hover{transform:translateY(-1px);}
.todo-tags-input{font-size:.78rem;padding:11px 12px;border:1.5px solid var(--border-color);border-radius:10px;background:var(--bg-white);color:var(--text-dark);min-width:130px;transition:border-color .2s;}
.todo-tags-input:focus{outline:none;border-color:#d17b96;}

.dark-mode .todo-search-input,.dark-mode .todo-tags-input{background:var(--bg-light);}

/* subtasks / checklist */
.todo-subtask-toggle{display:inline-flex;align-items:center;gap:5px;font-size:.66rem;font-weight:700;padding:2px 9px;border-radius:20px;border:none;background:var(--bg-light);color:var(--text-muted);cursor:pointer;transition:all .15s;width:fit-content;}
.todo-subtask-toggle:hover{color:#d17b96;background:rgba(219,113,175,.14);}
.todo-subtask-toggle.has-progress{background:rgba(219,113,175,.10);color:#a85870;}
.todo-subtask-toggle.all-done{background:rgba(34,197,94,.12);color:#16a34a;}
.todo-subtask-mini-bar{width:34px;height:4px;border-radius:4px;background:var(--border-color);overflow:hidden;display:inline-block;}
.todo-subtask-mini-fill{height:100%;background:linear-gradient(90deg,#d17b96,#f472b6);border-radius:4px;transition:width .3s;}
.todo-subtask-toggle.all-done .todo-subtask-mini-fill{background:linear-gradient(90deg,#22c55e,#4ade80);}

.todo-subtask-panel{flex-basis:100%;width:100%;margin-top:8px;padding:10px 10px 8px 34px;border-top:1px dashed var(--border-color);animation:todoFadeIn .2s ease both;}
.todo-subtask-item{display:flex;align-items:center;gap:8px;padding:4px 2px;}
.todo-subtask-item input[type="checkbox"]{width:15px;height:15px;flex-shrink:0;cursor:pointer;accent-color:#d17b96;}
.todo-subtask-text{flex:1;font-size:.79rem;color:var(--text-dark);word-break:break-word;}
.todo-subtask-item.done .todo-subtask-text{text-decoration:line-through;color:var(--text-muted);}
.todo-subtask-del{background:none;border:none;color:var(--text-muted);cursor:pointer;font-size:.7rem;padding:3px 6px;border-radius:5px;opacity:.45;transition:opacity .15s,color .15s,background .15s;flex-shrink:0;}
.todo-subtask-item:hover .todo-subtask-del{opacity:1;}
.todo-subtask-del:hover{color:#ef4444;background:rgba(239,68,68,.1);}
.todo-subtask-empty-hint{font-size:.72rem;color:var(--text-muted);padding:2px 2px 8px;}
.todo-subtask-add-row{display:flex;gap:6px;margin-top:4px;}
.todo-subtask-add-input{flex:1;font-size:.78rem;padding:7px 10px;border:1.5px solid var(--border-color);border-radius:8px;background:var(--bg-white);color:var(--text-dark);transition:border-color .2s;}
.todo-subtask-add-input:focus{outline:none;border-color:#d17b96;box-shadow:0 0 0 3px rgba(219,113,175,.12);}
.todo-subtask-add-btn{padding:7px 13px;background:linear-gradient(135deg,#d17b96,#a85870);color:#fff;border:none;border-radius:8px;font-size:.72rem;font-weight:700;cursor:pointer;transition:transform .15s,opacity .15s;}
.todo-subtask-add-btn:hover{transform:translateY(-1px);opacity:.92;}
.dark-mode .todo-subtask-add-input{background:var(--bg-light);}

/* groups */
.todo-group{margin-bottom:16px;animation:todoFadeIn .35s ease both;}
@keyframes todoFadeIn{from{opacity:0;transform:translateY(4px);}to{opacity:1;transform:translateY(0);}}
.todo-group-head{display:flex;align-items:center;gap:9px;margin-bottom:8px;padding:4px 2px;}
.todo-group-badge{font-size:.72rem;font-weight:800;padding:3px 11px;border-radius:20px;color:#fff;white-space:nowrap;box-shadow:0 2px 6px rgba(0,0,0,.15);letter-spacing:.3px;}
.todo-group-desc{font-size:.72rem;color:var(--text-muted);}
.todo-group-count{font-size:.68rem;font-weight:700;color:var(--text-muted);background:var(--bg-light);padding:2px 8px;border-radius:10px;margin-left:auto;}

/* rows */
.todo-row{display:flex;align-items:center;gap:10px;padding:10px 12px;border:1px solid var(--border-color);border-left:4px solid var(--p-color,#d17b96);border-radius:10px;margin-bottom:7px;background:var(--bg-white);box-shadow:var(--shadow-sm);transition:transform .15s,box-shadow .15s,opacity .3s,background .3s;flex-wrap:wrap;}
.todo-row:hover{transform:translateX(3px);box-shadow:var(--shadow-md);}
.todo-row.done{opacity:.55;border-left-color:var(--border-color);}
.todo-row.done:hover{transform:none;}
.todo-row.is-overdue{background:rgba(239,68,68,.06);border-left-color:#ef4444;}
.todo-row.is-today{background:rgba(249,115,22,.07);}
.todo-row.dragging{opacity:.9;box-shadow:var(--shadow-lg);cursor:grabbing;position:relative;z-index:60;}

.todo-drag-handle{cursor:grab;color:var(--text-muted);font-size:.8rem;flex-shrink:0;padding:4px 3px;line-height:1;touch-action:none;opacity:.5;transition:opacity .15s,color .15s;}
.todo-drag-handle:hover{opacity:1;color:#d17b96;}
.todo-drag-handle.disabled{opacity:.15;cursor:not-allowed;}

.todo-drop-empty{font-size:.72rem;color:var(--text-muted);text-align:center;padding:10px;border:1.5px dashed var(--border-color);border-radius:10px;margin-bottom:7px;opacity:.7;}

body.todo-dragging-active,body.todo-dragging-active *{user-select:none !important;-webkit-user-select:none !important;}

.todo-check{width:20px;height:20px;flex-shrink:0;cursor:pointer;accent-color:#d17b96;border-radius:6px;transition:transform .15s;}
.todo-check:hover{transform:scale(1.15);}

.todo-text-wrap{flex:1;min-width:120px;display:flex;flex-direction:column;gap:2px;}
.todo-text{font-size:.87rem;color:var(--text-dark);min-width:0;word-break:break-word;transition:color .2s;}
.todo-row.done .todo-text{text-decoration:line-through;color:var(--text-muted);}

.todo-due-badge{font-size:.66rem;font-weight:700;display:inline-flex;align-items:center;gap:4px;width:fit-content;padding:1px 8px;border-radius:20px;background:var(--bg-light);color:var(--text-muted);}
.todo-due-badge.overdue{background:rgba(239,68,68,.12);color:#ef4444;}
.todo-due-badge.today{background:rgba(249,115,22,.14);color:#ea580c;}
.todo-due-badge.soon{background:rgba(var(--theme-accent-3-rgb),.15);color:var(--theme-accent-3);}

.todo-prio-select{font-size:.68rem;font-weight:700;padding:3px 5px;border-radius:6px;border:1px solid var(--border-color);background:var(--bg-light);color:var(--text-dark);flex-shrink:0;cursor:pointer;}
.todo-due-input{font-size:.68rem;font-weight:600;padding:3px 5px;border-radius:6px;border:1px solid var(--border-color);background:var(--bg-light);color:var(--text-dark);flex-shrink:0;cursor:pointer;max-width:118px;}
.todo-due-input:focus{outline:none;border-color:#d17b96;}

.todo-move-btn,.todo-edit-btn,.todo-del-btn{background:none;border:none;font-size:.9rem;cursor:pointer;color:var(--text-muted);padding:3px 5px;flex-shrink:0;line-height:1;border-radius:6px;transition:color .15s,background .15s,transform .15s;}
.todo-move-btn:disabled{opacity:.2;cursor:default;}
.todo-move-btn:hover:not(:disabled){color:#d17b96;background:rgba(219,113,175,.12);transform:scale(1.1);}
.todo-edit-btn:hover{color:#d17b96;background:rgba(219,113,175,.12);transform:scale(1.1);}
.todo-del-btn:hover{color:#ef4444;background:rgba(239,68,68,.1);transform:scale(1.1);}

.todo-empty{font-size:.88rem;color:var(--text-muted);text-align:center;padding:40px 20px;background:var(--bg-light);border-radius:12px;border:1.5px dashed var(--border-color);}
.todo-empty-icon{font-size:2.2rem;display:block;margin-bottom:8px;animation:todoBounce 2s ease-in-out infinite;}
@keyframes todoBounce{0%,100%{transform:translateY(0);}50%{transform:translateY(-6px);}}

.todo-done-section{margin-top:20px;padding-top:14px;border-top:1px solid var(--border-color);}
.todo-done-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;cursor:pointer;padding:6px 4px;border-radius:8px;transition:background .15s;}
.todo-done-head:hover{background:rgba(219,113,175,.08);}
.todo-done-head span{font-size:.82rem;font-weight:700;color:var(--text-muted);}
.todo-clear-btn{padding:5px 12px;background:rgba(239,68,68,.08);color:#ef4444;border:1px solid rgba(239,68,68,.25);border-radius:8px;font-size:.72rem;font-weight:700;cursor:pointer;transition:background .15s,transform .15s;}
.todo-clear-btn:hover{background:rgba(239,68,68,.15);transform:translateY(-1px);}

.dark-mode .todo-row{background:var(--bg-white);}
.dark-mode .todo-row.is-overdue{background:rgba(239,68,68,.12);}
.dark-mode .todo-row.is-today{background:rgba(249,115,22,.14);}
.dark-mode .todo-prio-select,.dark-mode .todo-due-input{background:var(--bg-light);}
.dark-mode .todo-subtask-toggle{background:var(--bg-light);}
.dark-mode .todo-progress-wrap{background:var(--bg-white);}
.dark-mode .todo-empty{background:var(--bg-white);}
.dark-mode .todo-stat-chip{background:var(--bg-white);}
.dark-mode .todo-filter-btn{background:var(--bg-white);}
.dark-mode .todo-quick-due-btn{background:var(--bg-light);}

/* ── Todo Reminder Popup (shows on every page load) ── */
#todoReminderOverlay{position:fixed;inset:0;background:rgba(61, 40, 54,.55);backdrop-filter:blur(3px);z-index:99998;display:flex;align-items:center;justify-content:center;padding:16px;animation:trOverlayIn .25s ease both;}
@keyframes trOverlayIn{from{opacity:0;}to{opacity:1;}}
.todo-reminder-card{background:var(--bg-white,#fff);border-radius:16px;max-width:420px;width:100%;box-shadow:0 20px 60px rgba(0,0,0,.35);overflow:hidden;animation:trCardIn .35s cubic-bezier(.34,1.36,.64,1) both;}
@keyframes trCardIn{from{opacity:0;transform:translateY(16px) scale(.95);}to{opacity:1;transform:translateY(0) scale(1);}}
.todo-reminder-head{background:linear-gradient(135deg,#d17b96,#f472b6);padding:18px 20px;color:#fff;display:flex;align-items:center;gap:10px;}
.todo-reminder-head-icon{font-size:1.6rem;}
.todo-reminder-head-text{flex:1;}
.todo-reminder-head-title{font-size:1.02rem;font-weight:800;}
.todo-reminder-head-sub{font-size:.78rem;opacity:.9;}
.todo-reminder-body{padding:16px 20px;max-height:45vh;overflow-y:auto;}
.todo-reminder-item{display:flex;align-items:center;gap:9px;padding:8px 10px;border-radius:9px;margin-bottom:6px;background:var(--bg-light,#fffbfc);border-left:3px solid var(--p-color,#d17b96);}
.todo-reminder-item-badge{font-size:.65rem;font-weight:800;padding:2px 7px;border-radius:20px;color:#fff;background:var(--p-color,#d17b96);flex-shrink:0;}
.todo-reminder-item-text{font-size:.86rem;color:var(--text-dark,#4a3240);flex:1;min-width:0;word-break:break-word;}
.todo-reminder-more{font-size:.78rem;color:var(--text-muted,#9a7686);text-align:center;padding:4px 0 2px;}
.todo-reminder-actions{display:flex;gap:10px;padding:14px 20px 18px;}
.todo-reminder-btn{flex:1;padding:11px 14px;border-radius:10px;font-size:.86rem;font-weight:700;cursor:pointer;border:none;transition:transform .15s,opacity .15s;}
.todo-reminder-btn:active{transform:scale(.97);}
.todo-reminder-btn-primary{background:linear-gradient(135deg,#d17b96,#a85870);color:#fff;box-shadow:0 4px 12px rgba(219,113,175,.35);}
.todo-reminder-btn-secondary{background:var(--bg-light,#faf3f6);color:var(--text-muted,#9a7686);}
.dark-mode .todo-reminder-card{background:var(--bg-white);}
.dark-mode .todo-reminder-item{background:var(--bg-light);}
.dark-mode .todo-reminder-item-text{color:var(--text-dark);}
.dark-mode .todo-reminder-btn-secondary{background:var(--border-color);color:var(--text-muted);}
/* ── Icon system (SVG sprite via <use>, replaces emoji) — Calendar action bar ── */
.calact-icon {
  display:inline-block; width:14px; height:14px; flex-shrink:0; vertical-align:-2px;
  fill:none; stroke:currentColor; stroke-width:2; stroke-linecap:round; stroke-linejoin:round;
  margin-right:3px;
}
/* ═══ Planner polish ═══ */
/* Chữ trắng trên màu pastel khó đọc → phủ lớp tối nhẹ + viền trái + bóng chữ */
.cal-event {
    background-image: linear-gradient(rgba(0,0,0,.2), rgba(0,0,0,.2)) !important;
    border-left: 4px solid rgba(0,0,0,.22);
    text-shadow: 0 1px 1px rgba(0,0,0,.28);
    font-variant-numeric: tabular-nums;
}
.cal-event--short > div { align-items: center; }
.cal-event--short .cal-event-title { font-size:.72rem; }
.cal-event:focus-visible, .cal-tab:focus-visible, .cal-nav-btn:focus-visible, .cal-today-btn:focus-visible, .cal-free-slot:focus-visible {
    outline: 2px solid var(--primary); outline-offset: 2px;
}
/* Sự kiện trên lưới tuần */
.cal-week-cell { position: relative; }
.cal-week-evt {
    position: absolute; z-index: 2; box-sizing: border-box; overflow: hidden; cursor: pointer;
    border-radius: 6px; padding: 2px 5px; color: #fff; font-size: .68rem; font-weight: 600; line-height: 1.25;
    background-image: linear-gradient(rgba(0,0,0,.2), rgba(0,0,0,.2));
    border-left: 3px solid rgba(0,0,0,.25); text-shadow: 0 1px 1px rgba(0,0,0,.28);
    box-shadow: 0 1px 3px rgba(0,0,0,.18); transition: transform .12s, box-shadow .12s;
}
.cal-week-evt:hover { transform: scale(1.03); box-shadow: 0 3px 10px rgba(0,0,0,.28); z-index: 3; }
.cal-week-evt-title { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cal-week-evt-time { font-size: .62rem; opacity: .85; font-variant-numeric: tabular-nums; }
.cal-week-evt.is-past-event { opacity: .45; }
/* Tiêu đề cột ngày dính trên cùng khi cuộn tuần (overflow:clip không tạo scroll container nên sticky vẫn chạy) */
.cal-week-grid { overflow: clip; }
.cal-week-col-head { position: sticky; top: 0; z-index: 4; }
.cal-week-col-head, .cal-week-col-head.corner { background-color: var(--bg-light); }
.cal-week-col-head.today-col { background-color: var(--bg-light); background-image: linear-gradient(rgba(var(--primary-rgb),.1), rgba(var(--primary-rgb),.1)); }
#calBody:has(.cal-week-grid) { padding-top: 0; }
.cal-free-slot { opacity:.85; }
.cal-free-slot:hover { opacity:1; }
#calTabs { position:sticky; top:0; z-index:6; background:var(--bg-white); }
.cal-tab { white-space:nowrap; }
#calActionBar, .cal-legend { scrollbar-width:thin; }
@media (prefers-reduced-motion: reduce) { #calendarBox { animation:none; } .cal-event { transition:none; } }

/* ── Điện thoại: gọn phần đầu, dành chỗ cho lịch ── */
@media (max-width:700px) {
    #calendarModal { padding:0; align-items:flex-end; }
    #calendarBox { max-width:100%; max-height:96vh; height:96vh; border-radius:20px 20px 0 0; }
    #calHeader { padding:10px 14px 8px; gap:6px; }
    .cal-title { font-size:1rem; }
    .cal-nav-btn, .cal-today-btn { padding:5px 10px; font-size:.8rem; }
    #calActionBar { flex-wrap:nowrap !important; overflow-x:auto; padding:6px 12px !important; -webkit-overflow-scrolling:touch; }
    #calActionBar > * { flex-shrink:0; white-space:nowrap; }
    #calTabs { padding:8px 12px 0; gap:4px; }
    .cal-tab { flex:1; padding:7px 4px; font-size:.8rem; text-align:center; }
    .cal-legend { flex-wrap:nowrap; overflow-x:auto; padding:6px 14px; gap:12px; }
    .cal-legend-item { white-space:nowrap; flex-shrink:0; }
    #calBody { padding:12px 10px 18px; }
    .cal-week-grid { min-width:600px; }
    #calBody:has(.cal-week-grid) { overflow-x:auto; }
}

/* ═══ [3/38] <style> — originally at index.html line 21726 ═══ */
/* ── Reminder Toast Container ── */
#plannerReminderContainer {
  position: fixed;
  top: 20px;
  right: 20px;
  z-index: 99999;
  display: flex;
  flex-direction: column;
  gap: 10px;
  pointer-events: none;
  max-width: 340px;
}

.planner-reminder-toast {
  pointer-events: all;
  background: #4a3240;
  border-left: 4px solid var(--primary);
  border-radius: 12px;
  padding: 14px 16px;
  box-shadow: 0 8px 32px rgba(0,0,0,0.35), 0 0 0 1px rgba(var(--primary-rgb),0.3);
  display: flex;
  align-items: flex-start;
  gap: 12px;
  animation: reminderSlideIn 0.4s cubic-bezier(0.34,1.36,0.64,1) forwards;
  cursor: pointer;
  max-width: 340px;
  backdrop-filter: blur(8px);
  transform: translateZ(0); 
}

.dark-mode .planner-reminder-toast {
  background: #3d2836;
  box-shadow: 0 8px 32px rgba(0,0,0,0.55), 0 0 0 1px rgba(var(--primary-rgb),0.4);
}

.planner-reminder-toast.dismissing {
  animation: reminderSlideOut 0.3s ease forwards;
}

@keyframes reminderSlideIn {
  from { opacity: 0; transform: translateX(120%) scale(0.9); }
  to   { opacity: 1; transform: translateX(0) scale(1); }
}
@keyframes reminderSlideOut {
  from { opacity: 1; transform: translateX(0) scale(1); }
  to   { opacity: 0; transform: translateX(120%) scale(0.9); }
}

.reminder-icon {
  font-size: 1.6rem;
