}
.reminder-perm-desc {
  font-size: 0.8rem;
  color: var(--text-muted);
  margin-bottom: 14px;
  line-height: 1.5;
}
.reminder-perm-btns { display: flex; gap: 8px; }
.reminder-perm-btn {
  flex: 1;
  padding: 8px 12px;
  border-radius: 10px;
  border: 1px solid transparent;
  font: inherit;
  font-size: 0.8rem;
  font-weight: 700;
  cursor: pointer;
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
