  width: 30px; height: 30px; border-radius: 9px;
  border: none; color: var(--text-muted); background: var(--bg-light);
  cursor: pointer; font-size: 0.8rem; display: flex; align-items: center; justify-content: center;
  transition: all 0.15s; touch-action: manipulation;
}
.dlt-edit-btn:hover { background: #6366f1; color: #fff; }

/* ── Google Calendar button ── */
.dlt-gcal-btn {
  width: 30px; height: 30px; border-radius: 9px;
  border: none; color: var(--text-muted); background: var(--bg-light);
  cursor: pointer; font-size: 0.85rem; display: flex; align-items: center; justify-content: center;
  transition: all 0.15s; touch-action: manipulation;
}
.dlt-gcal-btn:hover { background: #4285f4; color: #fff; }

/* Clickable info zone for navigable cards */
.dlt-info.dlt-jumpable { cursor: pointer; }
.dlt-info.dlt-jumpable:hover .dlt-name {
  color: #f59e0b;
  text-decoration: underline dotted;
}
.dlt-info.dlt-jumpable::after {
  content: 'click to jump';
  font-size: 0.62rem; color: #f59e0b; opacity: 0;
  display: block; margin-top: 2px; font-style: italic;
  transition: opacity 0.2s;
}
.dlt-info.dlt-jumpable:hover::after { opacity: 0.8; }

.dlt-empty { color: var(--text-muted); font-size: 0.9rem; font-style: italic; }

/* ── Add Modal ── */
#dltModal {
  display: none; position: fixed; inset: 0;
  background: rgba(0,0,0,.52); z-index: 9999;
  align-items: center; justify-content: center; padding: 20px;
}
#dltModal.open { display: flex; }
.dlt-modal-box {
  background: var(--bg-white); border-radius: 18px; padding: 26px;
  width: 100%; max-width: 430px; box-shadow: var(--shadow-lg);
  max-height: 90vh; overflow-y: auto;
}
.dlt-modal-box h3 { margin: 0 0 20px; font-size: 1.15rem; font-weight: 700; color: var(--text-dark); }
.dlt-fg { margin-bottom: 14px; }
.dlt-fg label { display: block; font-size: 0.82rem; font-weight: 600; color: var(--text-muted); margin-bottom: 5px; }
.dlt-fg input, .dlt-fg select, .dlt-fg textarea {
  width: 100%; padding: 10px 12px; border: 1px solid var(--border-color);
  border-radius: 8px; font-size: 0.92rem; background: var(--bg-light);
  color: var(--text-dark); outline: none; -webkit-appearance: none;
  transition: border-color .2s; font-family: inherit;
}
.dlt-fg input:focus, .dlt-fg select:focus { border-color: #6366f1; }
.dlt-modal-actions { display: flex; gap: 10px; margin-top: 6px; }
.dlt-modal-save {
  flex: 1; padding: 11px;
  background: linear-gradient(135deg, #6366f1, #b892c9);
  color: #fff; border: none; border-radius: 8px; font-weight: 700; font-size: .93rem;
  cursor: pointer; touch-action: manipulation;
}
.dlt-modal-cancel {
  padding: 11px 16px; background: var(--bg-light); color: var(--text-muted);
  border: none; border-radius: 8px; font-weight: 600; font-size: .9rem;
  cursor: pointer; touch-action: manipulation;
}

/* ── Completed Deadlines Modal (large, scrollable) ── */
#dltCompletedModal {
  display: none; position: fixed; inset: 0;
  background: rgba(0,0,0,.55); z-index: 9999;
  align-items: flex-start; justify-content: center; padding: 30px 20px;
  overflow-y: auto;
}
#dltCompletedModal.open { display: flex; }
.dlt-cm-box {
  background: var(--bg-white); border-radius: 18px; padding: 24px 26px 30px;
  width: 100%; max-width: 820px; box-shadow: var(--shadow-lg);
  max-height: none;
}
.dlt-cm-header {
  display: flex; align-items: center; justify-content: space-between;
  margin-bottom: 18px; gap: 10px;
}
.dlt-cm-header h3 { margin: 0; font-size: 1.2rem; font-weight: 800; color: var(--text-dark); }
.dlt-cm-close {
  width: 34px; height: 34px; border-radius: 9px; border: none;
  background: var(--bg-light); color: var(--text-muted); font-size: 1rem;
  cursor: pointer; flex-shrink: 0; touch-action: manipulation;
}
.dlt-cm-close:hover { background: #fee2e2; color: #ef4444; }

/* Analytics stat grid */
.dlt-cm-stats {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px;
  margin-bottom: 20px;
}
.dlt-cm-stat {
  background: var(--bg-light); border-radius: 10px; padding: 12px 8px;
  text-align: center;
}
.dlt-cm-stat-n { font-size: 1.4rem; font-weight: 800; line-height: 1; color: var(--text-dark); }
.dlt-cm-stat-l { font-size: 0.66rem; font-weight: 700; text-transform: uppercase;
  letter-spacing: .3px; color: var(--text-muted); margin-top: 4px; }
.dlt-cm-stat.on-time .dlt-cm-stat-n { color: #10b981; }
.dlt-cm-stat.late    .dlt-cm-stat-n { color: #ef4444; }
.dlt-cm-stat.avg     .dlt-cm-stat-n { color: #6366f1; }

/* Chart area */
.dlt-cm-chart-wrap {
  display: flex; align-items: center; gap: 22px; margin-bottom: 22px;
  background: var(--bg-light); border-radius: 12px; padding: 16px;
  flex-wrap: wrap;
}
.dlt-cm-chart-canvas-box { width: 150px; height: 150px; flex-shrink: 0; position: relative; margin: 0 auto; }
.dlt-cm-chart-legend { flex: 1; min-width: 180px; display: flex; flex-direction: column; gap: 8px; }
.dlt-cm-legend-item { display: flex; align-items: center; gap: 8px; font-size: 0.83rem; color: var(--text-dark); }
.dlt-cm-legend-dot { width: 11px; height: 11px; border-radius: 3px; flex-shrink: 0; }

/* Completed list rows */
.dlt-cm-list { display: flex; flex-direction: column; gap: 10px; }
.dlt-cm-item {
  border: 1px solid var(--border-color); border-radius: 12px; padding: 12px 14px;
  border-left: 5px solid #10b981; background: var(--bg-white);
}
.dlt-cm-item-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; flex-wrap: wrap; }
.dlt-cm-item-name { font-weight: 700; font-size: 0.92rem; color: var(--text-dark); }
.dlt-cm-item-meta { font-size: 0.76rem; color: var(--text-muted); margin-top: 3px; }
.dlt-cm-badge {
  font-size: 0.68rem; font-weight: 700; padding: 3px 9px; border-radius: 8px;
  white-space: nowrap; flex-shrink: 0;
}
.dlt-cm-badge.early    { background: rgba(16,185,129,.14); color: #059669; }
.dlt-cm-badge.ontime   { background: rgba(99,102,241,.14); color: #6366f1; }
.dlt-cm-badge.late     { background: rgba(239,68,68,.14); color: #ef4444; }
.dlt-cm-undo-btn {
  font-size: 0.68rem; font-weight: 700; padding: 3px 10px; border-radius: 8px;
  border: 1px solid var(--border-color); background: var(--bg-light);
  color: var(--text-muted); cursor: pointer; white-space: nowrap; flex-shrink: 0;
  touch-action: manipulation;
}
.dlt-cm-undo-btn:hover { background: #fef3c7; color: #d97706; border-color: #fbbf24; }
.dlt-cm-note {
  margin-top: 9px; width: 100%; box-sizing: border-box; resize: vertical;
  min-height: 44px; padding: 8px 10px; border: 1px solid var(--border-color);
  border-radius: 8px; font-size: 0.82rem; font-family: inherit;
  background: var(--bg-light); color: var(--text-dark); outline: none;
  transition: border-color .15s;
}
.dlt-cm-note:focus { border-color: #6366f1; }
.dlt-cm-note-saved {
  font-size: 0.68rem; color: #10b981; font-weight: 700; margin-top: 4px;
  opacity: 0; transition: opacity .3s;
}
.dlt-cm-note-saved.show { opacity: 1; }
.dlt-cm-empty { color: var(--text-muted); font-size: 0.9rem; font-style: italic; padding: 20px 0; text-align: center; }

@media (max-width: 640px) {
  .dlt-cm-stats { grid-template-columns: repeat(2, 1fr); }
  .dlt-cm-chart-wrap { flex-direction: column; }
}

/* ── Weekly Digest Modal ── */
#dltDigestModal {
  display: none; position: fixed; inset: 0;
  background: rgba(0,0,0,.55); z-index: 9999;
  align-items: flex-start; justify-content: center; padding: 30px 20px;
  overflow-y: auto;
}
#dltDigestModal.open { display: flex; }
.dlt-dg-box { max-width: 640px; }
.dlt-dg-range { font-size: 0.82rem; color: var(--text-muted); font-weight: 600; margin: -10px 0 16px; }
.dlt-dg-overdue { border-radius: 12px; padding: 12px 14px; margin-bottom: 16px;
  background: rgba(239,68,68,.08); border: 1px solid rgba(239,68,68,.25); }
.dlt-dg-overdue .dlt-dg-day-title { color: #ef4444; }
.dlt-dg-day { margin-bottom: 16px; }
.dlt-dg-day:last-child { margin-bottom: 0; }
.dlt-dg-day-title { font-size: 0.85rem; font-weight: 800; color: var(--text-dark);
  margin-bottom: 8px; display: flex; align-items: baseline; gap: 6px; }
.dlt-dg-day-sub { font-size: 0.72rem; font-weight: 600; color: var(--text-muted); }
.dlt-dg-item { display: flex; align-items: flex-start; justify-content: space-between;
  gap: 10px; padding: 9px 12px; border-radius: 10px; background: var(--bg-light);
  margin-bottom: 6px; cursor: pointer; }
.dlt-dg-item:hover { background: var(--bg-hover, rgba(99,102,241,.08)); }
.dlt-dg-item:last-child { margin-bottom: 0; }
.dlt-dg-item-main { min-width: 0; }
.dlt-dg-item-name { font-weight: 700; font-size: 0.87rem; color: var(--text-dark);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dlt-dg-item-meta { font-size: 0.72rem; color: var(--text-muted); margin-top: 2px; }
.dlt-dg-item-badges { display: flex; gap: 5px; flex-shrink: 0; align-items: center; }
.dlt-dg-overdue-days { font-size: 0.68rem; font-weight: 800; color: #ef4444;
  background: rgba(239,68,68,.14); padding: 2px 8px; border-radius: 7px; white-space: nowrap; }
.dlt-dg-footer { margin-top: 18px; display: flex; justify-content: flex-end; }
.dlt-dg-copy-btn { padding: 9px 16px; border-radius: 10px; border: 0;
  background: var(--primary); color: #fff; font-weight: 700; font-size: 0.85rem;
  cursor: pointer; touch-action: manipulation; }
.dlt-dg-copy-btn:hover { filter: brightness(1.06); }
.dark-mode .dlt-dg-copy-btn { color: #2a1822; }

/* ── Daily Popup ── */
#dltPopup {
  display: none; position: fixed; bottom: 24px; right: 24px; z-index: 9998;
  background: var(--bg-white); color: var(--text-dark); border: 1px solid var(--border-color);
  border-radius: 18px; padding: 16px 16px 14px; max-width: 330px; width: 90%; overflow: hidden;
  box-shadow: 0 12px 34px rgba(var(--primary-rgb), .22), 0 2px 6px rgba(0,0,0,.08);
  animation: dltSlideIn .35s ease;
}
#dltPopup::before { content: ""; position: absolute; inset: 0 0 auto 0; height: 3px;
  background: linear-gradient(90deg, var(--primary), rgba(var(--primary-rgb), .25)); }
@keyframes dltSlideIn { from { opacity:0; transform:translateY(16px); } to { opacity:1; transform:translateY(0); } }
.dlt-popup-head { display: flex; align-items: center; gap: 10px; margin-bottom: 10px; }
.dlt-popup-ico { width: 32px; height: 32px; border-radius: 10px; display: grid; place-items: center; flex-shrink: 0;
  background: rgba(var(--primary-rgb), .16); color: var(--primary); }
#dltPopup h4 { margin: 0; font-size: .98rem; font-weight: 700; color: var(--text-dark); flex: 1; }
.dlt-popup-count { min-width: 24px; height: 22px; padding: 0 8px; border-radius: 999px; display: inline-grid; place-items: center;
  font-size: .74rem; font-weight: 700; color: var(--primary-dark); background: rgba(var(--primary-rgb), .16); }
.dlt-popup-items { margin-bottom: 12px; font-size: .84rem; color: var(--text-dark); }
.dlt-popup-item { display: flex; align-items: center; gap: 10px; padding: 8px 2px; border-bottom: 1px solid var(--border-color); }
.dlt-popup-item:last-child { border-bottom: 0; }
.dlt-pi-dot { width: 8px; height: 8px; border-radius: 50%; flex-shrink: 0; background: var(--primary); }
.dlt-popup-item.is-today .dlt-pi-dot { background: var(--dlt-icon-red, #ef4444); box-shadow: 0 0 0 3px rgba(239,68,68,.18); }
.dlt-popup-item.is-soon  .dlt-pi-dot { background: var(--dlt-icon-amber, #f59e0b); }
.dlt-pi-name { flex: 1; min-width: 0; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dlt-pi-when { flex-shrink: 0; font-size: .7rem; font-weight: 700; letter-spacing: .02em; padding: 3px 9px; border-radius: 999px;
  color: var(--text-muted); background: rgba(var(--primary-rgb), .1); }
.dlt-popup-item.is-today .dlt-pi-when { color: var(--dlt-icon-red, #ef4444); background: rgba(239,68,68,.14); }
.dlt-popup-item.is-soon  .dlt-pi-when { color: var(--dlt-icon-amber, #f59e0b); background: rgba(245,158,11,.14); }
.dlt-popup-btns { display: flex; gap: 8px; }
.dlt-popup-ok {
  flex: 1; display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 36px; padding: 0 12px;
  background: var(--primary); color: #fff; border: 0; border-radius: 10px; font-weight: 700; font-size: .84rem;
  cursor: pointer; touch-action: manipulation; transition: filter .15s, transform .15s;
}
.dlt-popup-ok:hover { filter: brightness(1.06); transform: translateY(-1px); }
.dark-mode .dlt-popup-ok { color: #2a1822; }
.dlt-popup-skip {
  height: 36px; padding: 0 14px; background: transparent; color: var(--text-muted);
  border: 1px solid var(--border-color); border-radius: 10px; font-size: .82rem; cursor: pointer; touch-action: manipulation;
}
.dlt-popup-skip:hover { color: var(--text-dark); border-color: var(--primary); }
.dlt-popup-ok:focus-visible, .dlt-popup-skip:focus-visible { outline: 2px solid var(--primary); outline-offset: 2px; }
@media (prefers-reduced-motion: reduce) { #dltPopup { animation: none; } .dlt-popup-ok { transition: none; } }

/* ── XP Flash ── */
.dlt-xp {
  position: fixed; top: 76px; right: 20px; z-index: 10000;
  background: linear-gradient(135deg, #10b981, #059669); color: #fff;
  padding: 10px 18px; border-radius: 20px; font-weight: 700; font-size: .88rem;
  box-shadow: 0 4px 16px rgba(16,185,129,.45);
  animation: dltXpIn .3s ease, dltXpOut .4s ease 2s forwards;
  pointer-events: none;
}
@keyframes dltXpIn  { from { opacity:0; transform:translateY(-8px) scale(.9); } to { opacity:1; transform:translateY(0) scale(1); } }
@keyframes dltXpOut { to { opacity:0; transform:translateY(-6px); } }

/* ── Quick Undo Toast (right after Mark Done) ── */
.dlt-undo-toast {
  position: fixed; bottom: 24px; left: 50%; transform: translateX(-50%);
  z-index: 10000; background: var(--text-dark); color: #fff;
  padding: 11px 12px 11px 18px; border-radius: 12px; font-size: .86rem;
  box-shadow: 0 6px 24px rgba(0,0,0,.28);
  display: flex; align-items: center; gap: 14px;
  animation: dltUndoIn .25s ease;
}
@keyframes dltUndoIn { from { opacity:0; transform:translateX(-50%) translateY(10px); } to { opacity:1; transform:translateX(-50%) translateY(0); } }
.dlt-undo-toast button {
  background: rgba(255,255,255,.15); color: #fff; border: none;
  padding: 6px 13px; border-radius: 8px; font-weight: 700; font-size: .82rem;
  cursor: pointer; touch-action: manipulation;
}
.dlt-undo-toast button:hover { background: rgba(255,255,255,.28); }

@media (max-width: 600px) {
  .dlt-card { max-width: 100%; }
  #dltPopup { bottom: 12px; right: 12px; left: 12px; width: auto; max-width: none; }
  .dlt-stats { gap: 8px; }
  .dlt-stat { min-width: 130px; padding: 10px 11px; gap: 9px; }
  .dlt-stat-icon { width: 32px; height: 32px; }
  .dlt-stat-icon .dlt-icon { width: 15px; height: 15px; }
  .dlt-stat-n { font-size: 1.25rem; }
}

/* ── Toolbar row (search + sort) ── */
.dlt-toolbar-row { display: flex; gap: 8px; align-items: center; margin-bottom: 10px; }
.dlt-toolbar-row .dlt-search-wrap { flex: 1; margin-bottom: 0; }
.dlt-sort-select {
  padding: 9px 10px; border-radius: 10px; border: 1px solid var(--border-color);
  background: var(--bg-white); color: var(--text-dark); font-size: .82rem; cursor: pointer;
  flex-shrink: 0; touch-action: manipulation;
}

/* ── Priority badges ── */
.dlt-badge.prio-high   { background: rgba(239,68,68,.14);  color: #ef4444; }
.dlt-badge.prio-medium { background: rgba(245,158,11,.14); color: #d97706; }
.dlt-badge.prio-low    { background: rgba(16,185,129,.14); color: #059669; }

/* ── Priority field color accent in modal ── */
#dltPriority { cursor: pointer; }

/* ── Snoozed card style ── */
.dlt-card.c-snoozed { opacity: .62; border-left-color: #b8919f; background: rgba(184, 145, 159,.04); }
.dlt-card.c-snoozed .dlt-days { color: #b8919f; }
.dlt-badge.snooze-badge { background: rgba(154, 118, 134,.14); color: #9a7686; display: inline-flex; align-items: center; gap: 5px; }
.dlt-badge.repeat-badge { background: rgba(99,102,241,.12); color: #6366f1; }
.dark-mode .dlt-badge.repeat-badge { background: rgba(129,140,248,.18); color: #a5b4fc; }
.dlt-snooze-x { cursor: pointer; font-weight: 700; }
.dlt-snooze-x:hover { color: #ef4444; }

/* ── Snooze control (button + popover menu) ── */
.dlt-snooze-wrap { position: relative; }
.dlt-snooze-btn {
  width: 30px; height: 30px; border-radius: 9px;
  border: none; color: var(--text-muted); background: var(--bg-light);
  cursor: pointer; font-size: 0.85rem; display: flex; align-items: center; justify-content: center;
  transition: all 0.15s; touch-action: manipulation;
}
.dlt-snooze-btn:hover { background: #f59e0b; color: #fff; }
.dlt-snooze-menu {
  display: none; position: absolute; right: 0; top: calc(100% + 4px);
  background: var(--bg-white); border: 1px solid var(--border-color); border-radius: 8px;
  box-shadow: var(--shadow-md); z-index: 20; flex-direction: column; min-width: 116px; overflow: hidden;
}
.dlt-snooze-menu.show { display: flex; }
.dlt-snooze-menu button {
  background: none; border: none; padding: 8px 12px; text-align: left; font-size: .8rem;
  color: var(--text-dark); cursor: pointer; white-space: nowrap; touch-action: manipulation;
}
.dlt-snooze-menu button:hover { background: var(--bg-light); }
.dlt-snooze-menu .dlt-snooze-custom {
  border-top: 1px solid var(--border-color); padding: 6px 10px 8px; display: flex; flex-direction: column; gap: 4px;
}
.dlt-snooze-menu .dlt-snooze-custom label { font-size: .68rem; color: var(--text-muted); font-weight: 700; text-transform: uppercase; letter-spacing: .3px; }
.dlt-snooze-menu .dlt-snooze-custom input[type="date"] {
  font-size: .78rem; padding: 4px 6px; border-radius: 6px; border: 1px solid var(--border-color);
  background: var(--bg-white); color: var(--text-dark);
}

/* ── Bulk "Snooze All" (for the Overdue group header) ── */
.dlt-group-header { position: relative; }
.dlt-snoozeall-wrap { margin-left: auto; position: relative; }
.dlt-snoozeall-btn {
  font-size: .7rem; font-weight: 700; text-transform: none; letter-spacing: 0;
  padding: 4px 10px; border-radius: 14px; border: 1.5px solid #f59e0b; color: #f59e0b;
  background: none; cursor: pointer; display: inline-flex; align-items: center; gap: 4px;
  touch-action: manipulation; -webkit-tap-highlight-color: transparent;
}
.dlt-snoozeall-btn:hover { background: #f59e0b; color: #fff; }
.dlt-snoozeall-menu {
  display: none; position: absolute; right: 0; top: calc(100% + 4px);
  background: var(--bg-white); border: 1px solid var(--border-color); border-radius: 8px;
  box-shadow: var(--shadow-md); z-index: 25; flex-direction: column; min-width: 150px; overflow: hidden;
}
.dlt-snoozeall-menu.show { display: flex; }
.dlt-snoozeall-menu button {
  background: none; border: none; padding: 8px 12px; text-align: left; font-size: .8rem;
  color: var(--text-dark); cursor: pointer; white-space: nowrap; touch-action: manipulation;
}
.dlt-snoozeall-menu button:hover { background: var(--bg-light); }

/* ── Push Deadline control (button + popover menu) — actually moves the
   real due date forward, unlike Snooze which only mutes the urgency UI.
   Works on every item, including auto-scanned courses/goals/deals. ── */
.dlt-push-wrap { position: relative; }
.dlt-push-btn {
  width: 30px; height: 30px; border-radius: 9px;
  border: none; color: var(--text-muted); background: var(--bg-light);
  cursor: pointer; font-size: 0.85rem; display: flex; align-items: center; justify-content: center;
  transition: all 0.15s; touch-action: manipulation;
}
.dlt-push-btn:hover { background: #6366f1; color: #fff; }
.dlt-push-menu {
  display: none; position: absolute; right: 0; top: calc(100% + 4px);
  background: var(--bg-white); border: 1px solid var(--border-color); border-radius: 8px;
  box-shadow: var(--shadow-md); z-index: 20; flex-direction: column; min-width: 132px; overflow: hidden;
}
.dlt-push-menu.show { display: flex; }
.dlt-push-menu button {
  background: none; border: none; padding: 8px 12px; text-align: left; font-size: .8rem;
  color: var(--text-dark); cursor: pointer; white-space: nowrap; touch-action: manipulation;
}
.dlt-push-menu button:hover { background: rgba(99,102,241,.12); }
.dlt-push-menu .dlt-push-custom {
  border-top: 1px solid var(--border-color); padding: 6px 10px 8px; display: flex; flex-direction: column; gap: 4px;
}
.dlt-push-menu .dlt-push-custom label { font-size: .68rem; color: var(--text-muted); font-weight: 700; text-transform: uppercase; letter-spacing: .3px; }
.dlt-push-menu .dlt-push-custom input[type="date"] {
  font-size: .78rem; padding: 4px 6px; border-radius: 6px; border: 1px solid var(--border-color);
  background: var(--bg-white); color: var(--text-dark);
}

/* ── Bulk "Push All" (for the Overdue group header) ── */
.dlt-pushall-wrap { position: relative; }
.dlt-pushall-btn {
  font-size: .7rem; font-weight: 700; text-transform: none; letter-spacing: 0;
  padding: 4px 10px; border-radius: 14px; border: 1.5px solid #6366f1; color: #6366f1;
  background: none; cursor: pointer; display: inline-flex; align-items: center; gap: 4px;
  touch-action: manipulation; -webkit-tap-highlight-color: transparent;
}
.dlt-pushall-btn:hover { background: #6366f1; color: #fff; }
.dlt-pushall-menu {
  display: none; position: absolute; right: 0; top: calc(100% + 4px);
  background: var(--bg-white); border: 1px solid var(--border-color); border-radius: 8px;
  box-shadow: var(--shadow-md); z-index: 25; flex-direction: column; min-width: 190px; overflow: hidden;
}
.dlt-pushall-menu.show { display: flex; }
.dlt-pushall-menu button {
  background: none; border: none; padding: 8px 12px; text-align: left; font-size: .8rem;
  color: var(--text-dark); cursor: pointer; white-space: nowrap; touch-action: manipulation;
}
.dlt-pushall-menu button:hover { background: rgba(99,102,241,.12); }

/* ── Multi-tag filtering (filter bar + per-card tag chips/editor) ── */
.dlt-tagbar {
  display: flex; flex-wrap: wrap; align-items: center; gap: 6px;
  margin: -4px 0 10px;
}
.dlt-tagbar-label {
  font-size: .7rem; font-weight: 700; color: var(--text-muted);
  text-transform: uppercase; letter-spacing: .3px; margin-right: 2px;
}
.dlt-tag-chip {
  font-size: .72rem; font-weight: 700; padding: 4px 11px; border-radius: 20px;
  border: 1.5px solid var(--border-color); background: var(--bg-white); color: var(--text-muted);
  cursor: pointer; touch-action: manipulation; -webkit-tap-highlight-color: transparent;
}
.dlt-tag-chip:hover { border-color: #a5b4fc; }
.dlt-tag-chip.active { background: #6366f1; border-color: #6366f1; color: #fff; }
.dlt-tag-mode-toggle {
  font-size: .68rem; font-weight: 700; padding: 4px 10px; border-radius: 20px;
  border: 1.5px dashed #a5b4fc; background: none; color: #6366f1; cursor: pointer;
  touch-action: manipulation;
}
.dlt-tag-clear {
  font-size: .72rem; font-weight: 700; padding: 4px 10px; border-radius: 20px;
  border: none; background: none; color: var(--text-muted); cursor: pointer;
  text-decoration: underline; touch-action: manipulation;
}

/* Small tag pills shown on each card (click = filter by that tag) */
.dlt-card-tags { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 5px; }
.dlt-card-tag {
  font-size: .66rem; font-weight: 700; padding: 2px 8px; border-radius: 14px;
  background: rgba(99,102,241,.1); color: #6366f1; cursor: pointer; white-space: nowrap;
  touch-action: manipulation;
}
.dlt-card-tag:hover { background: rgba(99,102,241,.2); }

/* Tag editor (button + popover), same pattern as Push/Snooze controls —
   works on every item including auto-scanned ones. */
.dlt-tag-wrap { position: relative; }
.dlt-tag-edit-btn {
  width: 30px; height: 30px; border-radius: 9px;
  border: none; color: var(--text-muted); background: var(--bg-light);
  cursor: pointer; font-size: 0.8rem; display: flex; align-items: center; justify-content: center;
  transition: all 0.15s; touch-action: manipulation;
}
.dlt-tag-edit-btn:hover { background: #6366f1; color: #fff; }
.dlt-tag-menu {
  display: none; position: absolute; right: 0; top: calc(100% + 4px);
  background: var(--bg-white); border: 1px solid var(--border-color); border-radius: 8px;
  box-shadow: var(--shadow-md); z-index: 20; flex-direction: column; min-width: 190px;
  padding: 10px; gap: 8px;
}
.dlt-tag-menu.show { display: flex; }
.dlt-tag-menu-chips { display: flex; flex-wrap: wrap; gap: 5px; }
.dlt-tag-menu-chips .dlt-card-tag { display: flex; align-items: center; gap: 4px; }
.dlt-tag-menu-chips .dlt-card-tag .x { font-weight: 800; opacity: .7; }
.dlt-tag-menu-chips .dlt-card-tag .x:hover { opacity: 1; }
.dlt-tag-menu-empty { font-size: .72rem; color: var(--text-muted); font-style: italic; }
.dlt-tag-menu input {
  font-size: .8rem; padding: 6px 8px; border-radius: 6px; border: 1px solid var(--border-color);
  background: var(--bg-white); color: var(--text-dark); width: 100%; box-sizing: border-box;
}

/* ── Note snippet on deadline card ── */
.dlt-note {
  position: relative; display: flex; flex-direction: column; gap: 4px;
  font-size: .78rem; color: var(--text-muted);
  margin-top: 6px; padding: 8px 10px 8px 11px; border-radius: 12px;
  background: linear-gradient(135deg, rgba(219,39,119,.07), rgba(99,102,241,.06));
  border: 1px solid rgba(219,113,175,.18); border-left: 3px solid #e879a8;
  cursor: pointer; transition: transform .18s ease, box-shadow .18s ease, background .18s ease, border-color .18s ease;
  -webkit-tap-highlight-color: transparent; outline: none;
}
.dlt-note:hover, .dlt-note:focus-visible {
  transform: translateY(-1px);
  background: linear-gradient(135deg, rgba(219,39,119,.12), rgba(99,102,241,.09));
  border-color: rgba(219,39,119,.38);
  box-shadow: 0 6px 16px -6px rgba(219,39,119,.35);
}
.dlt-note:focus-visible { box-shadow: 0 0 0 3px rgba(219,39,119,.25); }
.dlt-note:active { transform: scale(.985); }
.dlt-note-row { display: flex; align-items: flex-start; gap: 6px; min-width: 0; }
.dlt-note-icon { flex-shrink: 0; font-style: normal; color: #db2777; margin-top: 1px; display: inline-flex; }
/* Giới hạn 3 dòng, phần còn lại hiện "…" */
.dlt-note-text {
  flex: 1; min-width: 0; font-style: italic; line-height: 1.5;
  display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 3; line-clamp: 3;
  overflow: hidden; text-overflow: ellipsis;
  white-space: pre-line; word-break: break-word; overflow-wrap: anywhere;
}
.dlt-note-more {
  display: none; align-self: flex-end; align-items: center; gap: 3px;
  font-size: .68rem; font-weight: 700; font-style: normal; letter-spacing: .2px;
  color: #db2777; padding: 2px 8px; border-radius: 20px;
  background: rgba(219,39,119,.1); transition: background .15s, color .15s, gap .15s;
}
.dlt-note.is-clamped .dlt-note-more { display: inline-flex; }
.dlt-note:hover .dlt-note-more { background: #db2777; color: #fff; gap: 5px; }
body.dark-mode .dlt-note {
  background: linear-gradient(135deg, rgba(236,72,153,.13), rgba(129,140,248,.08));
  border-color: rgba(236,72,153,.22); border-left-color: #f472b6; color: #d9c4d3;
}
body.dark-mode .dlt-note-icon, body.dark-mode .dlt-note-more { color: #f9a8d4; }
body.dark-mode .dlt-note-more { background: rgba(236,72,153,.18); }
body.dark-mode .dlt-note:hover .dlt-note-more { background: #ec4899; color: #fff; }

/* ── Note popup (xem đầy đủ) ── */
#dltNoteModal {
  display: none; position: fixed; inset: 0; z-index: 10000;
  align-items: center; justify-content: center; padding: 20px;
  background: rgba(40,12,30,.5); backdrop-filter: blur(6px); -webkit-backdrop-filter: blur(6px);
}
#dltNoteModal.open { display: flex; animation: dltNmFade .2s ease; }
@keyframes dltNmFade { from { opacity: 0; } to { opacity: 1; } }
@keyframes dltNmPop { from { opacity: 0; transform: translateY(14px) scale(.96); } to { opacity: 1; transform: none; } }
.dlt-nm-box {
  position: relative; width: 100%; max-width: 560px; max-height: min(86vh, 720px);
  display: flex; flex-direction: column; overflow: hidden;
  border-radius: 22px; border: 1px solid rgba(219,113,175,.22);
  background: linear-gradient(165deg, #fffbfd 0%, #fdf1f7 100%);
  box-shadow: 0 30px 70px -20px rgba(190,24,93,.45), 0 8px 24px rgba(0,0,0,.12);
  animation: dltNmPop .28s cubic-bezier(.34,1.3,.64,1);
}
.dlt-nm-box::before {
  content: ''; position: absolute; left: 0; right: 0; top: 0; height: 4px;
  background: linear-gradient(90deg, #ec4899, #f59e0b, #8b5cf6);
}
.dlt-nm-head { display: flex; align-items: flex-start; gap: 12px; padding: 22px 20px 12px 22px; }
.dlt-nm-titlewrap { flex: 1; min-width: 0; }
.dlt-nm-title { margin: 0; font-size: 1.12rem; font-weight: 800; line-height: 1.35; color: var(--text-dark); word-break: break-word; }
.dlt-nm-meta { margin-top: 5px; display: flex; flex-wrap: wrap; align-items: center; gap: 6px 10px; font-size: .78rem; color: var(--text-muted); }
.dlt-nm-meta .dlt-icon { vertical-align: -2px; }
.dlt-nm-close {
  flex-shrink: 0; width: 34px; height: 34px; border-radius: 50%; border: none; cursor: pointer;
  display: inline-flex; align-items: center; justify-content: center;
  background: rgba(219,39,119,.09); color: #be185d; transition: all .18s;
}
.dlt-nm-close:hover { background: #db2777; color: #fff; transform: rotate(90deg); }
.dlt-nm-badges { display: flex; flex-wrap: wrap; gap: 6px; padding: 0 22px 12px; }
.dlt-nm-badges:empty { display: none; }
.dlt-nm-body {
  flex: 1; min-height: 0; overflow-y: auto; margin: 0 16px; padding: 14px 16px;
  border-radius: 14px; background: rgba(255,255,255,.7); border: 1px solid rgba(219,113,175,.16);
  font-size: .93rem; line-height: 1.75; color: var(--text-dark);
  white-space: pre-wrap; word-break: break-word; overflow-wrap: anywhere;
  scrollbar-width: thin; scrollbar-color: rgba(219,39,119,.35) transparent;
}
.dlt-nm-body::-webkit-scrollbar { width: 6px; }
.dlt-nm-body::-webkit-scrollbar-thumb { background: rgba(219,39,119,.35); border-radius: 6px; }
.dlt-nm-body a { color: #db2777; font-weight: 600; text-decoration: underline; text-underline-offset: 2px; }
.dlt-nm-body a:hover { color: #9d174d; }
.dlt-nm-foot { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; padding: 14px 16px 16px; }
.dlt-nm-count { margin-right: auto; font-size: .72rem; color: var(--text-muted); padding-left: 6px; }
.dlt-nm-btn {
  display: inline-flex; align-items: center; gap: 6px; padding: 9px 14px; border-radius: 11px;
  font-size: .82rem; font-weight: 700; border: 1px solid transparent; cursor: pointer;
  text-decoration: none; transition: all .16s; touch-action: manipulation; font-family: inherit;
}
.dlt-nm-btn.ghost { background: rgba(219,39,119,.08); color: #be185d; }
.dlt-nm-btn.ghost:hover { background: rgba(219,39,119,.16); transform: translateY(-1px); }
.dlt-nm-btn.primary { background: linear-gradient(135deg, #ec4899, #db2777 55%, #a855f7); color: #fff; box-shadow: 0 6px 16px -6px rgba(219,39,119,.6); }
.dlt-nm-btn.primary:hover { transform: translateY(-1px); box-shadow: 0 10px 22px -8px rgba(219,39,119,.7); }
.dlt-nm-btn.ok { background: rgba(16,185,129,.15); color: #059669; }
body.dark-mode .dlt-nm-box { background: linear-gradient(165deg, #2a1a2e 0%, #1f1424 100%); border-color: rgba(236,72,153,.25); }
body.dark-mode .dlt-nm-body { background: rgba(255,255,255,.05); border-color: rgba(236,72,153,.18); }
body.dark-mode .dlt-nm-body a { color: #f9a8d4; }
body.dark-mode .dlt-nm-close, body.dark-mode .dlt-nm-btn.ghost { background: rgba(236,72,153,.16); color: #f9a8d4; }
body.dark-mode .dlt-nm-btn.ghost:hover { background: rgba(236,72,153,.28); }
@media (max-width: 560px) {
  #dltNoteModal { padding: 0; align-items: flex-end; }
  .dlt-nm-box { max-width: 100%; max-height: 90vh; border-radius: 22px 22px 0 0; }
  .dlt-nm-btn { flex: 1; justify-content: center; }
  .dlt-nm-count { flex-basis: 100%; margin-bottom: 2px; }
}
@media (prefers-reduced-motion: reduce) {
  #dltNoteModal.open, .dlt-nm-box { animation: none; }
  .dlt-note, .dlt-nm-btn, .dlt-nm-close { transition: none; }
}

/* ── Attached link chip ── */
.dlt-link-chip {
  display: inline-flex; align-items: center; gap: 4px;
  font-size: .76rem; font-weight: 600; margin-top: 4px;
  padding: 5px 10px; border-radius: 14px; width: fit-content;
  text-decoration: none; cursor: pointer; transition: all .15s;
  background: rgba(99,102,241,.08); color: #6366f1; border: 1px solid rgba(99,102,241,.2);
}
.dlt-link-chip:hover { background: #6366f1; color: #fff; border-color: #6366f1; }
.dark-mode .dlt-link-chip { background: rgba(129,140,248,.14); color: #a5b4fc; border-color: rgba(129,140,248,.25); }
.dark-mode .dlt-link-chip:hover { background: #6366f1; color: #fff; }

/* ── Linked Roadmap milestone chip ── */
.dlt-rdmlink {
  display: inline-flex; align-items: center; gap: 5px;
  font-size: .76rem; font-weight: 600; margin-top: 4px;
  padding: 5px 10px; border-radius: 14px; cursor: pointer;
  border: 1px solid transparent; width: fit-content;
  transition: all .15s;
}
.dlt-rdmlink.rl-done     { background: rgba(5,150,105,.1);  color: #059669; border-color: rgba(5,150,105,.25); }
.dlt-rdmlink.rl-locked   { background: rgba(154, 118, 134,.1); color: #9a7686; border-color: rgba(154, 118, 134,.22); }
.dlt-rdmlink.rl-available{ background: rgba(99,102,241,.1);  color: #6366f1; border-color: rgba(99,102,241,.22); }
.dlt-rdmlink:hover { filter: brightness(0.95); }
.dlt-rdmlink .dlt-rdmlink-status { font-size: .68rem; }

/* ── Checklist (sub-tasks inside a manual deadline) ── */
.dlt-checklist-wrap { margin-top: 5px; }
.dlt-badge.checklist-toggle { cursor: pointer; background: rgba(99,102,241,.08); color: #6366f1; touch-action: manipulation; }
.dlt-checklist-panel {
  margin-top: 6px; padding: 8px; background: var(--bg-light); border-radius: 8px;
  display: flex; flex-direction: column; gap: 5px;
}
.dlt-checklist-item { display: flex; align-items: center; gap: 6px; font-size: .78rem; color: var(--text-dark); }
.dlt-checklist-item input[type=checkbox] { accent-color: #6366f1; cursor: pointer; flex-shrink: 0; }
.dlt-checklist-item span { flex: 1; min-width: 0; word-break: break-word; }
.dlt-checklist-item span.ck-done { text-decoration: line-through; color: var(--text-muted); }
.dlt-ck-del { flex-shrink: 0; background: none; border: none; color: var(--text-muted); cursor: pointer; font-size: .7rem; padding: 2px 4px; }
.dlt-ck-del:hover { color: #ef4444; }
.dlt-ck-empty { font-size: .75rem; color: var(--text-muted); font-style: italic; }
.dlt-ck-add-row { display: flex; gap: 5px; margin-top: 2px; }
.dlt-ck-add-input { flex: 1; min-width: 0; padding: 5px 8px; font-size: .76rem; border: 1px solid var(--border-color); border-radius: 6px; background: var(--bg-white); color: var(--text-dark); }
.dlt-ck-add-btn { padding: 5px 11px; border: none; border-radius: 6px; background: #6366f1; color: #fff; font-weight: 700; cursor: pointer; touch-action: manipulation; }

/* ── Confetti (on-time completion celebration) ── */
.dlt-confetti-container { position: fixed; inset: 0; pointer-events: none; z-index: 10001; overflow: hidden; }
.dlt-confetti-piece { position: absolute; top: -12px; width: 8px; height: 14px; opacity: .9; animation: dltConfettiFall linear forwards; }
@keyframes dltConfettiFall { to { transform: translateY(105vh) rotate(360deg); opacity: 0; } }

/* ── Completed-modal analytics: category table + insights + trend chart ── */
.dlt-cm-section-title { font-size: .85rem; font-weight: 800; color: var(--text-dark); margin: 4px 0 8px; }
.dlt-cm-cat-table { width: 100%; border-collapse: collapse; margin-bottom: 18px; font-size: .8rem; }
.dlt-cm-cat-table th, .dlt-cm-cat-table td { padding: 7px 8px; text-align: left; border-bottom: 1px solid var(--border-color); }
.dlt-cm-cat-table th { color: var(--text-muted); font-size: .7rem; text-transform: uppercase; letter-spacing: .3px; }
.dlt-cm-insight-box { display: flex; flex-direction: column; gap: 6px; margin-bottom: 18px; }
.dlt-cm-insight-item { background: rgba(99,102,241,.06); border-left: 3px solid #6366f1; border-radius: 8px; padding: 8px 12px; font-size: .82rem; color: var(--text-dark); }
.dlt-cm-trend-wrap { margin-bottom: 18px; }
.dlt-cm-trend-title { font-size: .85rem; font-weight: 800; color: var(--text-dark); margin-bottom: 8px; }
.dlt-cm-trend-canvas-box { height: 180px; }

/* ═══ [5/38] <style> — originally at index.html line 23708 ═══ */
/* ── Deadline density timeline (visual "which weeks are packed" bar) ──
   Wrapped as its own elevated card (matches .dlt-card / .dlt-summary-card
   styling elsewhere) instead of a bare row pinned between two border lines,
   so it reads as a distinct widget rather than a leftover strip. */
.dlt-timeline-wrap {
  margin: 2px 0 16px; background: var(--bg-white); border: 1px solid var(--border-color);
  border-radius: 12px; padding: 14px 12px 10px; box-shadow: var(--shadow-sm);
}
.dlt-timeline-title {
  font-size: .82rem; font-weight: 800; color: var(--text-dark);
  margin-bottom: 10px; display: flex; align-items: baseline; gap: 6px;
}
.dlt-timeline-sub { font-size: .72rem; font-weight: 600; color: var(--text-muted); }

.dlt-timeline {
  display: flex; align-items: flex-end; gap: 4px;
  padding: 4px 2px 0;
  overflow-x: auto; overflow-y: hidden;
}
.dlt-timeline::-webkit-scrollbar { height: 5px; }
.dlt-timeline::-webkit-scrollbar-track { background: transparent; }
.dlt-timeline::-webkit-scrollbar-thumb { background: var(--border-color); border-radius: 3px; }

.dlt-tl-col {
  flex: 1 1 0; min-width: 30px; display: flex; flex-direction: column;
  align-items: center; gap: 4px; padding: 6px 2px 8px;
  border-radius: 8px; position: relative; transition: background .15s ease;
}
.dlt-tl-col:hover { background: var(--bg-light); }
/* Visual break between "Overdue" (the past) and the upcoming weeks (the future) */
.dlt-tl-col.tl-overdue { margin-right: 5px; }
.dlt-tl-col.tl-overdue::after {
  content: ''; position: absolute; right: -5px; top: 8px; bottom: 16px; width: 1px;
  background: var(--border-color);
}

.dlt-tl-bar-track {
  width: 100%; max-width: 26px; height: 52px;
  display: flex; align-items: flex-end; justify-content: center;
  background: var(--bg-light); border: 1px solid var(--border-color);
  border-radius: 6px 6px 3px 3px; overflow: hidden;
}
.dlt-tl-bar {
  width: 100%; min-height: 4px; border-radius: 4px 4px 2px 2px;
  background-image: linear-gradient(180deg, rgba(255,255,255,.28), rgba(255,255,255,0) 55%);
  transition: height .3s cubic-bezier(.34,1.4,.64,1);
}
/* Empty weeks fade into the track instead of showing a full-strength color chip */
.dlt-tl-col.tl-empty .dlt-tl-bar { opacity: .3; }
/* The single busiest bucket gets a glow so the eye lands there first */
.dlt-tl-col.tl-peak .dlt-tl-bar { box-shadow: 0 0 0 1px rgba(255,255,255,.18), 0 3px 10px rgba(239,68,68,.4); }
.dlt-tl-col.tl-peak .dlt-tl-count { color: #ef4444; }

.dlt-tl-count { font-size: .7rem; font-weight: 800; color: var(--text-dark); min-height: 13px; line-height: 1; }
.dlt-tl-label {
  font-size: .6rem; color: var(--text-muted); font-weight: 700;
  text-transform: uppercase; letter-spacing: .3px;
}
.dlt-tl-col.tl-overdue .dlt-tl-label { color: #b8919f; }

/* ═══════════════════════════════════════════════════════════
   DEADLINES MODULE — blush-rose + champagne-gold theme
   Scoped to #dlTracker / #dltModal / #dltCompletedModal so the
   rest of the page is untouched. Urgency-status colors (red =
   urgent, amber = warning, green = safe/done, grey = overdue)
   are left as-is on purpose — those carry meaning at a glance.
   Only the neutral indigo/purple "chrome" (buttons, borders,
   focus rings, generic badges) is retinted to match the rest
   of the dashboard's new palette.
   ═══════════════════════════════════════════════════════════ */

#dlTracker,
.dlt-timeline-wrap {
  background: linear-gradient(160deg, #fdf5f9 0%, #fdf1f7 55%, #faf1ff 100%);
  border: 1px solid rgba(219, 113, 175, 0.18);
  box-shadow: 0 10px 26px rgba(219, 39, 119, 0.06);
}
body.dark-mode #dlTracker,
body.dark-mode .dlt-timeline-wrap {
  background: linear-gradient(160deg, #241726 0%, #2b1a2f 55%, #241a2c 100%);
  border-color: rgba(236, 72, 153, 0.2);
  box-shadow: 0 10px 26px rgba(0, 0, 0, 0.3);
}

/* Add / Digest / Select buttons — white by default, rose/gold gradient
   only on hover. Save button (in the Add/Edit modal) keeps the gradient
   always, since it's a primary action button, not a header pill. */
#dlTracker .dlt-btn {
  background: #fff !important;
  color: #db2777 !important;
  border: 1.5px solid rgba(219, 39, 119, 0.35) !important;
}
#dlTracker .dlt-btn:hover {
  background: linear-gradient(135deg, #db2777, #f6ad55) !important;
  color: #fff !important;
  border-color: transparent !important;
  box-shadow: 0 4px 14px rgba(219, 39, 119, 0.35) !important;
}
