                100% { box-shadow: 0 0 0 10px rgba(219, 113, 175, 0); }
            }
            @keyframes wlnTickPop {
                0% { opacity: 0; transform: translate(-50%, 4px) scale(0.6); }
                25% { opacity: 1; transform: translate(-50%, -6px) scale(1.15); }
                70% { opacity: 1; transform: translate(-50%, -14px) scale(1); }
