        --ed-btn:    var(--primary-dark);
        --ed-btn-ink:#fff;

        background: linear-gradient(160deg, color-mix(in srgb, var(--primary) 5%, var(--bg-white)) 0%, var(--bg-white) 70%) !important;
        border: 1px solid var(--ed-line) !important;
        border-radius: 18px !important;
        box-shadow: var(--shadow-md) !important;
