    /* ── header + context line ── */
    #englishDailyCard .ed-badge { font-size: 0.68rem; font-weight: 700; letter-spacing: 0.02em; padding: 2px 9px; border-radius: 999px; background: var(--ed-fill); color: var(--ed-accent); white-space: nowrap; }
