/* Duplicate btn in slot modal now uses the unified .cal-slot-btn styles (see .cal-slot-actions rules) */

/* ── Drag-to-resize handle ── */
.cal-resize-handle {
  position: absolute;
  bottom: 0; left: 0; right: 0;
  height: 10px;
  cursor: ns-resize;
  border-radius: 0 0 7px 7px;
  display: flex; align-items: center; justify-content: center;
  opacity: 0;
  transition: opacity .15s;
  z-index: 10;
  background: rgba(0,0,0,0.18);
